import {
  Suspense,
  lazy,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { FluentProvider } from "@fluentui/react-components";
import { ja } from "./strings/ja";
import { hsLightTheme, hsDarkTheme } from "./theme/fluentTheme";
import { useThemeMode } from "./theme/useThemeMode";
import { AppShell } from "./components/AppShell";
import { TitleBar } from "./components/TitleBar";
import { CommandBar } from "./components/CommandBar";
import { WaveformView } from "./components/WaveformView";
import { ScoreWorkspace } from "./components/ScoreWorkspace";
import { PropertiesPanel } from "./components/PropertiesPanel";
import {
  RequantizeDialog,
  requantizeSeed,
} from "./components/RequantizeDialog";
import { TransportBar } from "./components/TransportBar";
import { StatusBar } from "./components/StatusBar";
import { SettingsView } from "./components/SettingsView";
import { TranscriptionView } from "./components/TranscriptionView";
import { TranscriptionErrorView } from "./components/TranscriptionErrorView";
import { ExportDialog } from "./export/ExportDialog";
import { DiagnosticsSheet } from "./diagnostics/DiagnosticsSheet";
import { createDefaultExportPort } from "./export/port";
import type { ExportSource } from "./export/tauriPort";
import { exportErrorCode } from "./export/types";
import { createDefaultDiagnosticsPort } from "./diagnostics/port";
import { useAppSettings, type SettingsCategory } from "./settings/store";
import type { PitchView } from "./components/PitchSegmented";
import { createFixtureScoreDocument } from "./score/fixtureDocument";
import { scoreHandoffFromResult } from "./score/jobResult";
import {
  createEngineScoreDocument,
  engineDocumentFromResult,
} from "./score/xmlDocument";
import type { ScoreDocumentPort } from "./score/document";
import type { InspectorModel } from "./score/inspector";
import type { RhythmEditInvoker } from "./score/rhythmEdits";
import type {
  ScoreWorkspaceController,
  ScoreWorkspaceState,
} from "./score/controller";
import { openIssues } from "./score/review";
import { formatTimecode as formatScoreTimecode } from "./score/timecode";
import {
  createCommandRegistry,
  createCommandSurface,
  type CommandContext,
  type CommandSnapshot,
} from "./commands/registry";
import { KeyboardDispatcher } from "./keyboard/dispatcher";
import { useCommandKeyboard } from "./keyboard/useCommandKeyboard";
import { cycleFocusZone, focusZone } from "./focus/zones";
import { getShellInfo, isTauriRuntime } from "./tauri/bridge";
import {
  ImportController,
  parseProjectFile,
  type ImportState,
} from "./import/controller";
import { INITIAL_IMPORT_STATE } from "./import/controller";
import { loadRecentProjects, recordRecentProject } from "./import/recentProjects";
import { createImportPorts } from "./import/runtimePorts";
import { issueCopy, type ImportView } from "./import/ImportStates";
import { listenNativeDrop } from "./import/nativeDrop";
import { invoke } from "@tauri-apps/api/core";
import { buildProjectDocument } from "./import/project";
import { baseName } from "./import/formats";
import { CaptureController, type CaptureState } from "./capture/controller";
import {
  collectReferencedRecordingNames,
  getRecordingsInfo,
  pruneRecordings,
} from "./capture/recordings";
import { createCapturePort } from "./capture/runtimePorts";
import type { CaptureDeviceList, CaptureSource } from "./capture/types";
import {
  MediaElementTransport,
  SUPPORTED_RATES,
  type TransportSnapshot,
} from "./import/mediaTransport";
import {
  DEFAULT_TRANSCRIPTION_OPTIONS,
  type AudioFileRef,
  type TranscriptionOptions,
} from "./import/types";
import { buildTranscriptionParams } from "./import/transcriptionParams";
import { stageAudioForEngine } from "./import/staging";
import { formatTimecode } from "./import/format";
import { HsButton } from "./components/primitives/Button";
import { HsDialog } from "./components/primitives/Dialog";
import {
  regionVisibility,
  commandStateFor,
  SCREEN_STATES,
  type ScreenState,
} from "./workspace/screen";
import {
  TranscriptionSession,
  createDefaultSidecarPort,
  type EngineStatus,
} from "./sidecar";
import {
  inspectorHasContent,
  NO_SELECTION,
  type InspectorContent,
} from "./workspace/inspector";
import { useWorkspaceLayout } from "./workspace/layout";
import { initWindowGeometryPersistence } from "./workspace/windowGeometry";

type View = "workspace" | "settings";

/** "#/dev/gallery" — dev-only internal component gallery (UI-010). */
const GALLERY_HASH = "#/dev/gallery";
/** "#/dev/state/<screen>" — dev-only screen-state override so the
 *  responsive layout can be verified in every machine state (§27) before
 *  the real audio/score features land. No-op in packaged builds. */
const STATE_HASH_PREFIX = "#/dev/state/";
/**
 * "#/dev/transcribing" — dev-only entry that starts the shell in
 * AUDIO_READY and auto-invokes `score.transcribe` once mounted, so the
 * real UI-040 job flow (mock engine) runs end to end before UI-020's
 * file-open wiring lands. Unlike "#/dev/state/transcribing" (a static
 * layout preview) this runs an actual job.
 */
const DEV_TRANSCRIBING_HASH = "#/dev/transcribing";
// Lazy so the gallery (and its Fluent imports) stay out of the prod bundle.
const DevGallery = import.meta.env.DEV
  ? lazy(() => import("./dev/Gallery"))
  : null;

function screenFromHash(hash: string): ScreenState | null {
  if (!import.meta.env.DEV || !hash.startsWith(STATE_HASH_PREFIX)) return null;
  const name = hash.slice(STATE_HASH_PREFIX.length);
  return (SCREEN_STATES as readonly string[]).includes(name)
    ? (name as ScreenState)
    : null;
}

/** Japanese display name for a focus zone (for status announcements). */
function zoneName(id: string): string {
  const names: Record<string, string> = ja.commandFeedback.zoneNames;
  return names[id] ?? id;
}

/** Engine connection line for the status bar (解析エンジン: …). */
function engineStatusText(engine: EngineStatus): string {
  switch (engine) {
    case "ready":
      return ja.status.engineReady;
    case "starting":
      return ja.status.engineStarting;
    case "crashed":
      return ja.status.engineCrashed;
    case "unresponsive":
      return ja.status.engineUnresponsive;
    default:
      return ja.status.engineNotConnected;
  }
}

/**
 * HornScribe workspace shell (UI-011) driven by the UI-012 command
 * architecture (GUI_UX_SPEC §2/§21/§22/§23/§27). Information architecture:
 * single workspace, score is primary, properties collapse before the score
 * narrows, command overflow instead of horizontal scrolling, layout state
 * restored across restarts.
 *
 * The screen-state machine (§27) feeds the CommandSnapshot, so every
 * surface — command bar, transport, keyboard — agrees on enablement:
 * EMPTY mounts only 開く-level shell actions; 採譜 needs audio and is
 * disabled while transcribing; 要確認/書き出し need a score.
 */
export default function App() {
  const { mode, resolved, select } = useThemeMode();
  const [view, setView] = useState<View>("workspace");
  const [pitch, setPitch] = useState<PitchView>("concert");
  // UI-060: persisted settings (localStorage) + the two secondary surfaces
  // (書き出し dialog / 診断情報 sheet) that live outside the workspace.
  const { settings, update: updateSettings } = useAppSettings();
  const [exportOpen, setExportOpen] = useState(false);
  const [requantizeOpen, setRequantizeOpen] = useState(false);
  const [diagnosticsOpen, setDiagnosticsOpen] = useState(false);
  const [settingsFocus, setSettingsFocus] = useState<
    SettingsCategory | undefined
  >(undefined);
  // Ports are runtime-gated (mock in a browser, explicit-failure in the
  // Tauri shell until the engine spawn bridge lands — see export/port.ts).
  // #99: the Tauri port reads the live score document + audio name at
  // export time through this ref (state lives below; the port is
  // created once, so a ref keeps the getter fresh).
  const exportSourceRef = useRef<ExportSource | null>(null);
  const exportPort = useMemo(
    () => createDefaultExportPort(() => exportSourceRef.current),
    [],
  );
  const diagnosticsPort = useMemo(() => createDefaultDiagnosticsPort(), []);
  // User-specified tool paths (設定 → ツール) flow into every probe.
  const toolOverrides = useMemo(
    () => ({
      museScorePath: settings.museScorePath || undefined,
      ffmpegPath: settings.ffmpegPath || undefined,
    }),
    [settings.museScorePath, settings.ffmpegPath],
  );
  const [statusMessage, setStatusMessage] = useState<string>(ja.status.ready);
  const [shellDetail, setShellDetail] = useState<string | undefined>(
    ja.status.shellInfoLoading,
  );
  const [hash, setHash] = useState(() => window.location.hash);
  // Screen state machine (§27). The import flow (UI-020) drives
  // empty/openingAudio/audioReady/audioError/sourceMissing; the sidecar
  // session (UI-040) drives transcribing/transcriptionError/scoreReady.
  // Dev builds can override via "#/dev/state/<name>" or auto-start a real
  // job via "#/dev/transcribing".
  const [screen, setScreen] = useState<ScreenState>(() =>
    import.meta.env.DEV && window.location.hash === DEV_TRANSCRIBING_HASH
      ? "audioReady"
      : "empty",
  );
  // A canonical score exists — survives failed/cancelled retranscription
  // (issue rule: partial failure never destroys valid state).
  const [hasScore, setHasScore] = useState(false);
  const [engineRestarting, setEngineRestarting] = useState(false);
  const layout = useWorkspaceLayout();

  // The session is created once per App mount; the default port is the
  // mock outside Tauri and the gated port inside (src/sidecar/README.md).
  const session = useMemo(
    () => new TranscriptionSession({ portFactory: createDefaultSidecarPort }),
    [],
  );
  const [sessionSnap, setSessionSnap] = useState(() => session.getSnapshot());

  useEffect(() => {
    const unsub = session.subscribe(setSessionSnap);
    return () => {
      unsub();
      // App shutdown → graceful engine.shutdown (bounded, never throws).
      void session.dispose();
    };
  }, [session]);

  const job = sessionSnap.job;
  const jobPhase = job?.phase;

  // [UI-030] the document behind SCORE_READY+: built once a transcription
  // completes — identity + review issues come from the job result
  // (score/jobResult.ts); the notation body stays on the committed fixture
  // until the engine ships MusicXML through the same port.
  const [scoreDocument, setScoreDocument] =
    useState<ScoreDocumentPort | null>(null);
  const [inspectorModel, setInspectorModel] = useState<InspectorModel>({
    kind: "empty",
  });
  const [scoreState, setScoreState] = useState<ScoreWorkspaceState | null>(null);
  const scoreCtlRef = useRef<ScoreWorkspaceController | null>(null);

  // §27 transitions driven by the job lifecycle. Terminal phases are
  // consumed once (session.clearJob) — retry is never silent.
  useEffect(() => {
    if (!jobPhase) return;
    if (jobPhase === "completed") {
      setHasScore(true);
      // ENG-002: a real engine result carries MusicXML — build the
      // document from it. The mock/dev result carries none, so the
      // deterministic fixture stays the honest fallback there.
      const engineInput = engineDocumentFromResult(sessionSnap.lastResult);
      const handoff = scoreHandoffFromResult(sessionSnap.lastResult);
      const engineDoc =
        engineInput !== null
          ? createEngineScoreDocument({
              ...engineInput,
              issues: handoff?.issues ?? [],
            })
          : null;
      setScoreDocument(engineDoc ?? createFixtureScoreDocument(handoff));
      setScreen("scoreReady");
      setStatusMessage(ja.transcription.completed);
      session.clearJob();
    } else if (jobPhase === "cancelled") {
      setScreen(hasScore ? "scoreReady" : "audioReady");
      setStatusMessage(ja.transcription.cancelled);
      session.clearJob();
    }
    // `failed` also sets snap.failure — the screen mapping lives on the
    // failure flag below so crash/unresponsive land identically.
  }, [jobPhase, hasScore, session, sessionSnap.lastResult]);

  // §27: fail → TRANSCRIPTION_ERROR. Set by a terminal `failed` event
  // (job error) or by crash/unresponsive supervision while a job ran.
  useEffect(() => {
    if (sessionSnap.failure) setScreen("transcriptionError");
  }, [sessionSnap.failure]);

  /* ---- UI-020 import flow ---- */
  // The transport adapter (UI-004 contract) is created once per app; the
  // import controller feeds it decoded media sources on AUDIO_READY.
  const transport = useMemo(() => new MediaElementTransport(), []);
  const [transportSnap, setTransportSnap] =
    useState<TransportSnapshot | null>(null);
  const [importState, setImportState] =
    useState<ImportState>(INITIAL_IMPORT_STATE);
  const [recentProjects, setRecentProjects] = useState(() =>
    loadRecentProjects(),
  );
  const [nativeDrag, setNativeDrag] = useState(false);
  const [transcriptionOptions, setTranscriptionOptions] =
    useState<TranscriptionOptions>(DEFAULT_TRANSCRIPTION_OPTIONS);
  // 設定→採譜は採譜オプションの既定値: 新しい音源を開くたびに
  // 設定値でリセットする(表示だけの死んだ設定にしない)。
  useEffect(() => {
    if (!importState.audio) return;
    setTranscriptionOptions({
      ...DEFAULT_TRANSCRIPTION_OPTIONS,
      tempo: settings.tempoMode,
      tempoBpm: settings.tempoMode === "manual" ? settings.bpm : null,
      meter: settings.meter,
      minDuration: { eighth: "8", sixteenth: "16", thirtySecond: "32" }[
        settings.minDuration
      ],
      // 「三連符を使う」off は候補を生成しない none。on は既定の
      // region-gated 自動判定(auto)に任せる — always だと全拍に
      // 三連符候補が乗り既定挙動が変わるため。
      triplets: settings.triplets ? "auto" : "none",
    });
  }, [importState.audio, settings]);

  // #99: keep the export port's source getter current — the doc plus a
  // basename derived from the loaded audio's file name (extension
  // stripped), matching the ENG-001 `<basename>_<artifact>` policy.
  useEffect(() => {
    const fileName = importState.audio?.fileName ?? "";
    const stem = fileName.replace(/\.[^.]*$/, "");
    // #87: path-backed refs can be bundled into the export; in-browser
    // bytes (kind:"file" drops, pathless recordings) cannot be copied.
    const ref = importState.audio?.ref;
    const audioPath =
      ref?.kind === "path"
        ? ref.path
        : ref?.kind === "recording"
          ? (ref.path ?? null)
          : null;
    exportSourceRef.current = scoreDocument
      ? {
          doc: scoreDocument,
          basename: stem || scoreDocument.meta.title,
          audioPath,
          audioName: audioPath ? fileName || null : null,
        }
      : null;
  }, [scoreDocument, importState.audio]);

  // FEAT-001 (#60): capture session state (loopback / microphone).
  const [captureState, setCaptureState] =
    useState<CaptureState | null>(null);
  // #76: 録音開始前の「現在の音源を置き換える」確認ダイアログ。
  const [pendingCapture, setPendingCapture] =
    useState<CaptureSource | null>(null);
  // #73: 取り込みデバイス選択(capture_devices の結果)。
  const [captureDevices, setCaptureDevices] =
    useState<CaptureDeviceList | null>(null);

  const importer = useMemo(
    () =>
      new ImportController(
        createImportPorts(),
        {
          onScreenChange: (s) => setScreen(s),
          onState: (s) => setImportState(s),
          onRecentChange: (entries) => setRecentProjects([...entries]),
          announce: setStatusMessage,
          onAudioReady: (audio) => {
            // Fire-and-forget: a media failure flips the transport snapshot
            // to "error" — the status line already carries the outcome.
            void transport.load(audio.mediaSource).catch(() => undefined);
          },
          onProjectScoreReady: (result) => {
            // #106: the saved extras mirror the completed-job result —
            // rebuild the document and land on SCORE_READY without
            // re-transcribing. Malformed extras fall back to the
            // fixture document only in dev; with a real result null
            // means no usable MusicXML, so keep the audio-only state.
            const input = engineDocumentFromResult(result);
            if (!input) return;
            const handoff = scoreHandoffFromResult(result);
            const doc = createEngineScoreDocument({
              ...input,
              issues: handoff?.issues ?? [],
            });
            if (!doc) return;
            setHasScore(true);
            setScoreDocument(doc);
            // Keep the SOURCE_MISSING card on screen when the audio
            // still needs relinking — the score is ready underneath
            // and lands when the relink succeeds.
            setScreen((s) => (s === "sourceMissing" ? s : "scoreReady"));
          },
        },
        // Recent-project MRU persists in localStorage (web + webview).
        typeof window !== "undefined" ? window.localStorage : null,
      ),
    [transport],
  );

  // FEAT-001: the capture controller pushes recorded audio straight into
  // the import flow — a finished take lands as AUDIO_READY exactly like a
  // picked file (single-document app: the new source replaces the old).
  const capture = useMemo(
    () =>
      new CaptureController(createCapturePort(), {
        onState: (s) => setCaptureState(s),
        announce: setStatusMessage,
        onCaptureComplete: ({ path, bytes, fileName, source, mimeType }) => {
          // Tauri: 録音は appDataDir/recordings/ に保存済み(#70)なので
          // path を渡し、import 側で読み直す。ブラウザ dev 等で path が
          // 無い場合は bytes → Blob を渡す。
          const blob = bytes
            ? new Blob(
                [
                  new Uint8Array(
                    new Uint8Array(
                      bytes.buffer,
                      bytes.byteOffset,
                      bytes.byteLength,
                    ),
                  ),
                ],
                { type: mimeType ?? "audio/wav" },
              )
            : undefined;
          void importer.importRecording({
            kind: "recording",
            name: fileName,
            source,
            path,
            blob,
          });
        },
      }),
    [importer],
  );
  useEffect(() => () => capture.dispose(), [capture]);

  // 設定→再生: 標準再生速度はライブ設定なので即時反映する
  // (transport.setRate は [0.25,4] にクランプ済み)。
  useEffect(() => {
    transport.setRate(settings.playbackRate);
  }, [transport, settings.playbackRate]);

  // #87: 保持日数ポリシー — 起動時に一度だけ古い録音を削除する。
  // settings.recordingsRetentionDays は起動時の値で確定(途中変更は
  // 次回起動から有効)。削除件数はステータスバーで知らせる。
  useEffect(() => {
    const days = settings.recordingsRetentionDays;
    if (days <= 0) return;
    /* #132: recordings a saved project still references are excluded
     * from the retention sweep — deleting them would leave the project
     * openable but source-less. Only the recordings dir is protected;
     * unreadable projects fail open (their refs stay unknown). */
    void (async () => {
      const ports = createImportPorts();
      const info = await getRecordingsInfo();
      const keep = await collectReferencedRecordingNames({
        readProjectBytes: ports.readProjectBytes,
        entries: loadRecentProjects(),
        dir: info?.dir ?? null,
        sourcePathOf: async (blob) =>
          parseProjectFile(await blob.arrayBuffer(), "").sourcePath,
      });
      const n = await pruneRecordings(days, keep);
      if (n > 0) setStatusMessage(ja.settings.recordingsPruned(n));
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- run once
  }, []);

  // #81: 録音中にアプリを閉じると録音は失われる。WebView2/Tauri でも
  // beforeunload の preventDefault は閉じる確認として扱われるため、
  // 録音中だけガードを掛ける(録音していない時の常駐確認はしない)。
  const recordingActive = captureState?.phase === "recording";
  useEffect(() => {
    if (!recordingActive) return;
    const guard = (e: BeforeUnloadEvent) => {
      e.preventDefault();
    };
    window.addEventListener("beforeunload", guard);
    return () => window.removeEventListener("beforeunload", guard);
  }, [recordingActive]);

  // #73: デバイス一覧はメニューを開く度に取り直す(抜き差しに追従)。
  const refreshCaptureDevices = useCallback(() => {
    void capture
      .listDevices()
      .then(setCaptureDevices)
      .catch(() => setCaptureDevices(null));
  }, [capture]);

  // #76: 録音は現在の音源(と楽譜)を置き換える単一ドキュメントのため、
  // 既に音源がある時は開始前に確認する。録音中に演奏が鳴っていると
  // ループバック/マイクに混入するので、開始時に audition は切る。
  const requestCapture = useCallback(
    (source: CaptureSource) => {
      if (importState.audio || scoreDocument) {
        setPendingCapture(source);
        return;
      }
      if (scoreState?.auditionEnabled) scoreCtlRef.current?.toggleAudition();
      void capture.start(source);
    },
    [capture, importState.audio, scoreDocument, scoreState?.auditionEnabled],
  );
  const confirmCapture = useCallback(() => {
    const source = pendingCapture;
    setPendingCapture(null);
    if (!source) return;
    if (scoreState?.auditionEnabled) scoreCtlRef.current?.toggleAudition();
    void capture.start(source);
  }, [capture, pendingCapture, scoreState?.auditionEnabled]);

  const regions = regionVisibility(screen);

  // [UI-030] Feature inspector model → the shell's selection contract: the
  // panel auto-opens on real selections and stays closed otherwise (§6).
  const inspector: InspectorContent = useMemo(
    () =>
      inspectorModel.kind === "note"
        ? { kind: "note", noteId: inspectorModel.canonicalId ?? "" }
        : NO_SELECTION,
    [inspectorModel],
  );
  const propertiesVisible = regions.properties && layout.propertiesOpen;
  // Open-issue count prefers the live workspace mirror (UI-050: it tracks
  // decisions as they resolve); then the document's static list; then the
  // job result count for the window before the document mounts; the
  // dev-state REVIEWING placeholder stays so its surfaces can be reviewed.
  const reviewCount =
    scoreState?.openIssueCount ??
    (scoreDocument
      ? openIssues(scoreDocument.reviewIssues()).length
      : sessionSnap.reviewIssueCount > 0
        ? sessionSnap.reviewIssueCount
        : screen === "reviewing"
          ? 12
          : 0);

  // The registry is static: predicates read the snapshot, not React state.
  const registry = useMemo(() => createCommandRegistry(), []);

  // Screen machine → command snapshot (§23). Playback fields mirror the
  // transport adapter (UI-020) or, when no media source is loaded, the
  // score clock (UI-030 dev/fixture playback); isTranscribing keeps
  // score-writing commands disabled while a transcription runs (§5).
  const snapshot = useMemo<CommandSnapshot>(
    () => ({
      ...commandStateFor(screen),
      hasScore: commandStateFor(screen).hasScore && scoreDocument !== null,
      isPlaying:
        transportSnap?.status === "playing" ||
        (scoreState?.isPlaying ?? false),
      loopEnabled:
        transportSnap?.loop != null || (scoreState?.loopEnabled ?? false),
      pitch,
      // UI-050: undo/redo reach the score workspace's review/edit history.
      canUndo: scoreState?.canUndo ?? false,
      canRedo: scoreState?.canRedo ?? false,
      hasSelection: scoreState?.hasSelection ?? false,
      // #113: the waveform range selection (AUDIO_READY) is Esc-clearable
      // like a score selection (spec 8).
      hasWaveformSelection:
        screen === "audioReady" && transcriptionOptions.range === "selection",
      reviewOpen: scoreState?.reviewOpen ?? screen === "reviewing",
      reviewCount,
      view,
      // FEAT-001: recording + audition gates for the command registry.
      isRecording: captureState?.phase === "recording",
      isRecordingPaused:
        captureState?.phase === "recording" && captureState.paused,
      auditionEnabled: scoreState?.auditionEnabled ?? false,
    }),
    [screen, scoreDocument, transportSnap, scoreState, pitch, reviewCount, view, captureState, transcriptionOptions],
  );

  // Whether the media transport carries a loaded source — then it is the
  // authoritative clock and the score follows via the transport prop
  // (UI-005 one-clock contract). Otherwise transport commands fall back to
  // the score clock (dev/fixture playback with no audio loaded).
  const mediaLive =
    transportSnap != null && transportSnap.status !== "empty";

  // §8 §-seek transport step (GUI_UX_SPEC §9: ←/→ 5 seconds).
  const seekBy = useCallback(
    (delta: number) => {
      void transport
        .seek(transport.getCurrentTime() + delta)
        .catch(() => undefined);
      setStatusMessage(
        ja.import.feedback.position(
          formatTimecode(transport.getCurrentTime()),
        ),
      );
    },
    [transport],
  );

  // #100: プロジェクトを保存 — pick a path, build the schema-v1
  // document, and let the engine validate + atomically write it. The
  // flow is async behind a fire-and-forget command entry.
  const saveProjectFlow = useCallback(async () => {
    const doc = scoreDocument;
    if (!doc) {
      setStatusMessage(ja.notifications.projectSaveFailed);
      return;
    }
    if (!isTauriRuntime()) {
      // Browser dev has no save picker — the honest limitation, not a
      // silent no-op (same posture as the other Tauri-only commands).
      setStatusMessage(ja.notifications.projectSaveUnsupported);
      return;
    }
    try {
      const project = await buildProjectDocument({
        audio: importState.audio,
        doc,
        result: sessionSnap.lastResult,
      });
      if (!project) {
        setStatusMessage(ja.notifications.projectSaveUnsupported);
        return;
      }
      const fileName = importState.audio?.fileName ?? "score";
      const suggested = fileName.replace(/\.[^.]*$/, "") || "score";
      const path = await invoke<string | null>("project_save_path", {
        suggestedName: `${suggested}.hornscribe.json`,
      });
      if (!path) return; // cancelled — no announcement needed
      const res = await session.saveProject(path, project);
      const name = res.path.split(/[\\/]/).pop() ?? res.path;
      setRecentProjects(recordRecentProject({ name, path: res.path }));
      setStatusMessage(ja.notifications.projectSaved);
    } catch {
      setStatusMessage(ja.notifications.projectSaveFailed);
    }
  }, [scoreDocument, importState.audio, sessionSnap.lastResult, session]);

  // #115 (spec 13): engine rhythm edits — the score workspace delegates
  // to the live engine's score.edit; the same worker that produced the
  // score re-realizes the edited measures (one worker, one caller, so
  // no extra spawn cost beyond the lazy ensureEngine).
  const applyRhythmEdit = useCallback<RhythmEditInvoker>(
    (scoreDocPayload, op) => session.applyScoreEdit(scoreDocPayload, op),
    [session],
  );

  const ctx = useMemo<CommandContext>(
    () => ({
      openAudio: () => void importer.openViaDialog(),
      transcribe: () => {
        // §27 AUDIO_READY → TRANSCRIBING. The job lifecycle effects own
        // every later transition; a failed start lands on the §20 surface.
        setScreen("transcribing");
        setStatusMessage(ja.transcription.start);
        // #86: browser-held bytes (kind:"file" drops, pathless
        // recordings) are staged to a temp file first so the real
        // engine gets a readable audioPath; refs already on disk
        // return null from staging and keep their own path.
        void stageAudioForEngine(importState.audio)
          .then((staged) =>
            session.startTranscription(
              buildTranscriptionParams(
                importState.audio,
                transcriptionOptions,
                staged,
                settings.backend,
              ),
            ),
          )
          .catch(() => {
            /* failure flag drives the error surface */
          });
      },
      cancelTranscription: () => {
        // Cooperative job.cancel — the terminal `cancelled` event is the
        // real transition; the button shows キャンセルしています… until then.
        session.cancelTranscription().catch(() => {
          /* JOB_NOT_FOUND races are ignored in the session; other
            failures surface through snap.failure/engine state */
        });
      },
      togglePlayPause: () => {
        if (transport.getSnapshot().status !== "empty") {
          // [UI-020] real audio clock — the score follows it through the
          // transport prop mirror (ScoreReadyWorkspace sync effect).
          if (transport.getSnapshot().status === "playing") {
            transport.pause();
            setStatusMessage(ja.import.feedback.paused);
          } else {
            void transport.play().catch(() => undefined);
            setStatusMessage(ja.import.feedback.playing);
          }
        } else {
          // No audio source loaded — the score clock is the transport
          // (fixture/dev playback, UI-030).
          const c = scoreCtlRef.current;
          if (c) c.togglePlayPause();
          else setStatusMessage(ja.score.empty);
        }
      },
      stop: () => {
        if (transport.getSnapshot().status !== "empty") {
          transport.stop();
          setStatusMessage(ja.import.feedback.stopped);
        } else {
          const c = scoreCtlRef.current;
          if (c) c.stop();
          else setStatusMessage(ja.score.empty);
        }
      },
      jumpBack: () => {
        if (transport.getSnapshot().status !== "empty")
          seekBy(-settings.skipSeconds);
        else scoreCtlRef.current?.jumpBy(-settings.skipSeconds * 1000);
      },
      jumpForward: () => {
        if (transport.getSnapshot().status !== "empty")
          seekBy(settings.skipSeconds);
        else scoreCtlRef.current?.jumpBy(settings.skipSeconds * 1000);
      },
      seekToStart: () => {
        if (transport.getSnapshot().status !== "empty") {
          void transport.seek(0).catch(() => undefined);
          setStatusMessage(
            ja.import.feedback.position(formatTimecode(0)),
          );
        } else {
          scoreCtlRef.current?.seekToStart();
        }
      },
      seekToEnd: () => {
        if (transport.getSnapshot().status !== "empty") {
          void transport
            .seek(transport.getDuration())
            .catch(() => undefined);
          setStatusMessage(
            ja.import.feedback.position(
              formatTimecode(transport.getDuration()),
            ),
          );
        } else {
          scoreCtlRef.current?.seekToEnd();
        }
      },
      // Loop arming is score-side when a score exists (UI-030 owns the
      // range contract: the score clock wraps inside the range and the
      // score draws passage marks). #113: the media transport mirrors the
      // same range so the *audio* loops too - and before any score exists
      // (AUDIO_READY) the loop button arms the media A-B loop directly,
      // over the waveform selection when one is committed.
      toggleLoop: () => {
        const c = scoreCtlRef.current;
        if (c) {
          c.toggleLoop();
          const range = c.loopRange?.();
          transport.setLoop(
            range
              ? { start: range.startMs / 1000, end: range.endMs / 1000 }
              : null,
          );
          return;
        }
        if (transportSnap && transportSnap.status !== "empty") {
          if (transportSnap.loop) {
            transport.setLoop(null);
            setStatusMessage(ja.commandFeedback.loopOff);
          } else {
            const sel =
              transcriptionOptions.range === "selection" &&
              transcriptionOptions.selectionStartSec != null &&
              transcriptionOptions.selectionEndSec != null
                ? {
                    start: transcriptionOptions.selectionStartSec,
                    end: transcriptionOptions.selectionEndSec,
                  }
                : { start: 0, end: transportSnap.duration };
            transport.setLoop(sel);
            setStatusMessage(ja.commandFeedback.loopOn);
          }
        } else {
          setStatusMessage(ja.commandFeedback.disabled);
        }
      },
      // FEAT-001: capture + score audition commands.
      captureSystemAudio: () => {
        requestCapture("loopback");
      },
      captureMicrophone: () => {
        requestCapture("microphone");
      },
      stopCapture: () => {
        void capture.stop();
      },
      cancelCapture: () => {
        void capture.cancel();
      },
      pauseCapture: () => {
        void capture.pause();
      },
      resumeCapture: () => {
        void capture.resume();
      },
      toggleScoreAudition: () => {
        const c = scoreCtlRef.current;
        if (c) c.toggleAudition();
        else setStatusMessage(ja.commandFeedback.disabled);
      },
      toggleSourceMute: () => {
        transport.setMuted(!(transportSnap?.muted ?? false));
        setStatusMessage(
          transportSnap?.muted
            ? ja.commandFeedback.unmutedSource
            : ja.commandFeedback.mutedSource,
        );
      },
      setPitchView: (v) => {
        setPitch(v);
        setStatusMessage(
          v === "concert"
            ? ja.commandFeedback.pitchConcert
            : ja.commandFeedback.pitchHornF,
        );
      },
      openReview: () => scoreCtlRef.current?.openReview(),
      reviewNext: () => scoreCtlRef.current?.reviewNext(),
      reviewPrevious: () => scoreCtlRef.current?.reviewPrevious(),
      // UI-050 review actions — all live in the score workspace session.
      reviewAccept: () => scoreCtlRef.current?.reviewAccept(),
      reviewDismiss: () => scoreCtlRef.current?.reviewDismiss(),
      reviewPlaySource: () => scoreCtlRef.current?.reviewPlaySource(),
      reviewPitchUp: () => scoreCtlRef.current?.reviewPitch(1),
      reviewPitchDown: () => scoreCtlRef.current?.reviewPitch(-1),
      reviewDeleteOrRestore: () =>
        scoreCtlRef.current?.reviewDeleteOrRestore(),
      exitReview: () => scoreCtlRef.current?.exitReview(),
      undo: () => {
        const c = scoreCtlRef.current;
        if (c) c.undo();
        else setStatusMessage(ja.commandFeedback.nothingToUndo);
      },
      redo: () => {
        const c = scoreCtlRef.current;
        if (c) c.redo();
        else setStatusMessage(ja.commandFeedback.nothingToRedo);
      },
      openExport: () => setExportOpen(true),
      // §13 高度編集: open the live score (current pitch view, edits
      // included) in the MuseScore GUI. The port resolves the detected/
      // user-pinned executable; missing MuseScore announces the 設定 →
      // ツール recovery path instead of a dead menu item.
      openInMuseScore: () => {
        void exportPort
          .openInMuseScore?.(pitch, toolOverrides)
          .then(() => setStatusMessage(ja.commandFeedback.museScoreOpened))
          .catch((err: unknown) =>
            setStatusMessage(
              exportErrorCode(err) === "MUSESCORE_UNAVAILABLE"
                ? ja.commandFeedback.museScoreMissing
                : ja.commandFeedback.museScoreFailed,
            ),
          );
      },
      // #100: プロジェクトを保存 — pick a path (Tauri) then hand the
      // schema-v1 document to the engine's project.save. In a plain
      // browser there is no save picker, so the command announces the
      // honest limitation instead of faking a write.
      saveProject: () => {
        void saveProjectFlow();
      },
      zoomScoreIn: () => scoreCtlRef.current?.zoomIn(),
      zoomScoreOut: () => scoreCtlRef.current?.zoomOut(),
      zoomScoreFit: () => scoreCtlRef.current?.zoomFit(),
      clearSelection: () => scoreCtlRef.current?.clearSelection(),
      // #113: Esc on a waveform selection drops the committed range and
      // returns the transcription-range option to "all" (spec 8).
      clearWaveformSelection: () => {
        if (transcriptionOptions.range === "selection") {
          setTranscriptionOptions({ ...transcriptionOptions, range: "all" });
        }
      },
      // #114: score note navigation + direct edits (spec 10/13).
      selectAdjacentNote: (direction) =>
        scoreCtlRef.current?.selectAdjacentNote?.(direction),
      editSelectedPitch: (delta) =>
        scoreCtlRef.current?.editSelectedPitch?.(delta),
      toggleSelectedDeleted: () =>
        scoreCtlRef.current?.toggleSelectedDeleted?.(),
      toggleSelectedEnharmonic: () =>
        scoreCtlRef.current?.toggleSelectedEnharmonic?.(),
      // #115: engine rhythm edits (spec 13) — duration ladder, onset
      // grid shift, tie toggle. The workspace runs them through the
      // serialized score.edit queue; these just forward.
      noteDurationScale: (power) =>
        scoreCtlRef.current?.noteDurationScale?.(power),
      shiftSelectedOnset: (steps) =>
        scoreCtlRef.current?.shiftSelectedOnset?.(steps),
      toggleSelectedTie: () =>
        scoreCtlRef.current?.toggleSelectedTie?.(),
      // #130 (spec 14): quantization-settings dialog — app-owned
      // surface; the workspace controller applies the requantize edit.
      openRequantizeDialog: () => setRequantizeOpen(true),
      // #131 (spec 13 post-MVP): split/merge via the workspace.
      splitSelectedNote: () =>
        scoreCtlRef.current?.splitSelectedNote?.(),
      mergeSelectedNotes: () =>
        scoreCtlRef.current?.mergeSelectedNotes?.(),
      openSettings: () => {
        setSettingsFocus(undefined);
        setView("settings");
      },
      openDiagnostics: () => setDiagnosticsOpen(true),
      // F6 / Shift+F6 region cycling (§22) — owned by focus/zones.ts; these
      // are the only fully-working transport-independent commands so far.
      focusNextRegion: () => {
        const zone = cycleFocusZone(1);
        if (zone) {
          setStatusMessage(ja.commandFeedback.focusMoved(zoneName(zone)));
        }
      },
      focusPreviousRegion: () => {
        const zone = cycleFocusZone(-1);
        if (zone) {
          setStatusMessage(ja.commandFeedback.focusMoved(zoneName(zone)));
        }
      },
      announce: setStatusMessage,
    }),
    [importer, transport, seekBy, session, capture, requestCapture, transportSnap, importState.audio, transcriptionOptions, settings.skipSeconds, settings.backend, saveProjectFlow, pitch, toolOverrides, exportPort],
  );

  // The dispatcher reads the snapshot lazily per key event, so it must see
  // the latest render's value even though the listener is stable.
  const snapshotRef = useRef(snapshot);
  snapshotRef.current = snapshot;
  const dispatcher = useMemo(
    () =>
      new KeyboardDispatcher({
        registry,
        getSnapshot: () => snapshotRef.current,
        context: ctx,
      }),
    [registry, ctx],
  );
  useCommandKeyboard(dispatcher);

  // One render-scoped invocation surface shared by command bar, transport
  // and any other component — buttons never call services directly.
  const commands = useMemo(
    () => createCommandSurface(registry, ctx, snapshot),
    [registry, ctx, snapshot],
  );

  // Closing the panel returns focus to the score region when the focus was
  // inside the panel (§22 focus discipline); if it was closed from the
  // overflow menu, focus stays where it is.
  const closeProperties = useCallback(() => {
    const focusInside =
      document
        .querySelector('.hs-properties')
        ?.contains(document.activeElement) ?? false;
    layout.setPropertiesOpen(false);
    if (focusInside) {
      requestAnimationFrame(() => focusZone("score"));
    }
  }, [layout]);

  // §6: the panel opens itself when a real selection exists; with nothing
  // selected it stays closed until the user reopens it manually.
  useEffect(() => {
    if (
      inspectorHasContent(inspector) &&
      regions.properties &&
      !layout.propertiesOpen
    ) {
      layout.setPropertiesOpen(true);
    }
  }, [inspector, regions.properties, layout]);

  // 採譜 start routes through the command surface — the registry decides
  // (disabled → honest announcement, never a silent no-op). Cancellation
  // is owned by TranscriptionView via score.cancelTranscription (§5).
  const transcribeClicked = useCallback(() => {
    if (!commands.invoke("score.transcribe")) {
      setStatusMessage(ja.commandFeedback.disabled);
    }
  }, [commands]);

  // Hash routing: internal dev gallery + dev screen-state override. The
  // product shell is a single workspace (§2), not a page router.
  useEffect(() => {
    const onHashChange = () => {
      const h = window.location.hash;
      setHash(h);
      const forced = screenFromHash(h);
      if (forced) {
        // Score states need a document — the deterministic fixture adapter
        // supplies one until engine output flows through the job result.
        if (commandStateFor(forced).hasScore) {
          setHasScore(true);
          setScoreDocument((doc) => doc ?? createFixtureScoreDocument());
        }
        setScreen(forced);
        setView("workspace");
      }
    };
    window.addEventListener("hashchange", onHashChange);
    onHashChange();
    return () => window.removeEventListener("hashchange", onHashChange);
  }, []);

  // Dev-only entry: "#/dev/transcribing" auto-starts a real job once the
  // shell is up so the whole TRANSCRIBING flow can be reviewed directly.
  const devAutoStarted = useRef(false);
  useEffect(() => {
    if (
      import.meta.env.DEV &&
      hash === DEV_TRANSCRIBING_HASH &&
      !devAutoStarted.current
    ) {
      devAutoStarted.current = true;
      commands.invoke("score.transcribe");
    }
  }, [hash, commands]);

  // §26 session restore: window geometry (size/position) persists across
  // restarts; panel sizes/visibility persist via useWorkspaceLayout.
  useEffect(() => {
    let alive = true;
    let unlisten: (() => void) | undefined;
    void initWindowGeometryPersistence().then((u) => {
      if (alive) unlisten = u;
      else u();
    });
    return () => {
      alive = false;
      unlisten?.();
    };
  }, []);

  // §27 SCORE_READY ⇄ REVIEWING (UI-050): the review bar lives inside the
  // score workspace, so the screen machine mirrors its open flag — region
  // chrome, command predicates (reviewOpen) and the dev-state surface all
  // read the same truth. Transitions are deliberately limited to the
  // scoreReady/reviewing pair so EXPORTING is never hijacked.
  const scoreReviewOpen = scoreState?.reviewOpen;
  useEffect(() => {
    if (screen === "scoreReady" && scoreReviewOpen === true) {
      setScreen("reviewing");
    } else if (screen === "reviewing" && scoreReviewOpen === false) {
      setScreen("scoreReady");
    }
  }, [screen, scoreReviewOpen]);

  // Prove the JS↔Rust IPC channel early; populates the status area.
  useEffect(() => {
    let alive = true;
    getShellInfo().then((info) => {
      if (!alive) return;
      setShellDetail(
        info ? `v${info.version}` : undefined, // browser dev: no shell info
      );
      setStatusMessage(ja.status.ready);
    });
    return () => {
      alive = false;
    };
  }, []);

  // Transport adapter → low-frequency snapshot for playhead + transport
  // bar (media timeupdate cadence, no rAF — see mediaTransport.ts header).
  useEffect(() => {
    const unsubscribe = transport.subscribe(setTransportSnap);
    setTransportSnap(transport.getSnapshot());
    return () => {
      unsubscribe();
      transport.dispose();
    };
  }, [transport]);

  // Native file drop (Tauri `dragDropEnabled`): enter/over light the drop
  // affordance on the score region, drop imports the first supported path.
  // Outside the webview this resolves to a no-op (HTML5 drop covers dev).
  useEffect(() => {
    let alive = true;
    let unlisten: (() => void) | undefined;
    void listenNativeDrop((payload) => {
      if (payload.type === "enter" || payload.type === "over") {
        setNativeDrag(true);
      } else if (payload.type === "leave") {
        setNativeDrag(false);
      } else {
        setNativeDrag(false);
        // 録音中のドロップは onDropFiles と同じゲート — 取り込み済みの
        // 録音を黙って上書きしない。
        if (captureState?.phase === "recording") return;
        const refs: AudioFileRef[] = payload.paths.map((path) => ({
          kind: "path",
          path,
          name: baseName(path),
        }));
        void importer.importRefs(refs);
      }
    }).then((u) => {
      if (alive) unlisten = u;
      else u();
    });
    return () => {
      alive = false;
      unlisten?.();
    };
  }, [importer, captureState?.phase]);

  // Assembled once per render for the import-owned score bodies
  // (ImportStates.tsx) — keeps ScoreWorkspace's prop surface small.
  const importView = useMemo<ImportView>(
    () => ({
      audio: importState.audio,
      openingLabel: importState.openingLabel,
      openingKind: importState.openingKind,
      issue: importState.issue,
      sourceMissing: importState.sourceMissing,
      recentProjects,
      options: transcriptionOptions,
      onOpenAudio: () => void importer.openViaDialog(),
      onOpenProject: (entry) => void importer.openProject(entry),
      onPickRelink: () => void importer.pickRelinkSource(),
      onDismissError: () => importer.dismiss(),
      onOptionsChange: setTranscriptionOptions,
      // FEAT-001: EMPTY state capture entry points.
      captureState,
      onStartCapture: (source) => {
        requestCapture(source);
      },
    }),
    [importState, recentProjects, transcriptionOptions, importer, captureState, requestCapture],
  );

  const theme = resolved === "dark" ? hsDarkTheme : hsLightTheme;
  // Dev-only route: the gallery renders in place of the shell and never
  // appears in product navigation.
  const showGallery = DevGallery != null && hash === GALLERY_HASH;

  return (
    // .hs-provider fixes the UI-009 latent bug: the FluentProvider wrapper
    // div had no definite height, so `height:100%` on .hs-shell collapsed
    // to content height. The provider now owns the full viewport.
    <FluentProvider theme={theme} className="hs-provider">
      {showGallery ? (
        <Suspense fallback={null}>
          <DevGallery themeMode={mode} onThemeMode={select} />
        </Suspense>
      ) : (
        <AppShell>
          {/* Document identity follows the loaded source audio (§2). */}
          <TitleBar documentTitle={importState.audio?.fileName} />
          {view === "settings" ? (
            <div className="hs-settings-wrap">
              <SettingsView
                themeMode={mode}
                onThemeMode={select}
                onBack={() => setView("workspace")}
                settings={settings}
                onSettingsChange={updateSettings}
                diagnosticsPort={diagnosticsPort}
                exportPort={exportPort}
                onOpenDiagnostics={() => setDiagnosticsOpen(true)}
                onAnnounce={setStatusMessage}
                focusCategory={settingsFocus}
              />
            </div>
          ) : (
            <>
              <CommandBar
                commands={commands}
                pitch={pitch}
                screen={screen}
                reviewCount={reviewCount}
                compact={layout.breakpoint === "compact"}
                propertiesOpen={layout.propertiesOpen}
                onToggleProperties={() =>
                  layout.setPropertiesOpen(!layout.propertiesOpen)
                }
                captureState={captureState}
                captureDevices={captureDevices}
                captureSelectedDevice={(source) =>
                  capture.selectedDeviceId(source)
                }
                onSelectCaptureDevice={(source, id) => {
                  capture.selectDevice(source, id);
                  // 選択は localStorage 側に持つので React state は
                  // 変わらない — ✓ を即座に反映するため再描画を起こす。
                  setCaptureDevices((d) => (d ? { ...d } : d));
                }}
                onCaptureMenuOpen={refreshCaptureDevices}
              />
              {regions.waveform ? (
                <WaveformView
                  height={layout.waveformHeight}
                  min={layout.waveformMin}
                  max={layout.waveformMax}
                  onResize={layout.requestWaveformHeight}
                  onReset={layout.resetWaveformHeight}
                  audio={importState.audio}
                  loading={screen === "openingAudio"}
                  positionSec={transportSnap?.time}
                  onSeek={(s) => {
                    void transport.seek(s).catch(() => undefined);
                  }}
                  captureState={captureState}
                  selection={
                    screen === "audioReady" &&
                    transcriptionOptions.range === "selection"
                      ? {
                          startSec: transcriptionOptions.selectionStartSec ?? 0,
                          endSec:
                            transcriptionOptions.selectionEndSec ??
                            (importState.audio?.durationSeconds ?? 0),
                        }
                      : null
                  }
                  onSelect={
                    screen === "audioReady"
                      ? (range) =>
                          setTranscriptionOptions({
                            ...transcriptionOptions,
                            range: "selection",
                            selectionStartSec: range.startSec,
                            selectionEndSec: range.endSec,
                          })
                      : undefined
                  }
                  // #113: armed media loop band + selection context
                  // actions (spec 8: ループ/再生/ズーム/解除).
                  loop={
                    transportSnap?.loop
                      ? {
                          startSec: transportSnap.loop.start,
                          endSec: transportSnap.loop.end,
                        }
                      : null
                  }
                  onLoopSelection={(range) => {
                    if (transportSnap?.loop) transport.setLoop(null);
                    else {
                      transport.setLoop({
                        start: range.startSec,
                        end: range.endSec,
                      });
                      setStatusMessage(ja.commandFeedback.loopOn);
                    }
                  }}
                  onPlaySelection={(range) => {
                    void transport
                      .playRange(range.startSec, range.endSec)
                      .catch(() => undefined);
                  }}
                  onClearSelection={() => {
                    if (transcriptionOptions.range === "selection") {
                      setTranscriptionOptions({
                        ...transcriptionOptions,
                        range: "all",
                      });
                    }
                  }}
                />
              ) : null}
              <div className="hs-main">
                <ScoreWorkspace
                  screen={screen}
                  importView={importView}
                  externalDragActive={nativeDrag}
                  onDropFiles={(files) =>
                    // 録音中のドロップは取り込み済み録音を黙って上書きする
                    // ので受け付けない(file.openAudio と同じゲート)。
                    captureState?.phase === "recording"
                      ? undefined
                      : void importer.importRefs(
                          files.map<AudioFileRef>((file) => ({
                            kind: "file",
                            file,
                            name: file.name,
                          })),
                        )
                  }
                  onTranscribe={transcribeClicked}
                  transcribingBody={
                    <TranscriptionView job={job} commands={commands} />
                  }
                  transcriptionErrorBody={
                    <TranscriptionErrorView
                      kind={sessionSnap.failure?.kind ?? "transcriptionFailed"}
                      restarting={engineRestarting}
                      diagnostics={() => session.buildDiagnostics()}
                      onPrimary={() => {
                        const failure = sessionSnap.failure;
                        if (!failure || failure.kind === "transcriptionFailed") {
                          // 再試行 is explicit — never a silent resubmit.
                          setScreen("transcribing");
                          setStatusMessage(ja.transcription.start);
                          session.clearFailure();
                          void stageAudioForEngine(importState.audio)
                            .then((staged) =>
                              session.startTranscription(
                                buildTranscriptionParams(
                                  importState.audio,
                                  transcriptionOptions,
                                  staged,
                                  settings.backend,
                                ),
                              ),
                            )
                            .catch(() => undefined);
                        } else {
                          // エンジンを再起動 — the §20 crash recovery action.
                          setEngineRestarting(true);
                          session
                            .restartEngine()
                            .then(() => {
                              session.clearFailure();
                              setScreen(hasScore ? "scoreReady" : "audioReady");
                              setStatusMessage(ja.status.engineRestarted);
                            })
                            .catch(() => {
                              /* failure stays set — surface remains */
                            })
                            .finally(() => setEngineRestarting(false));
                        }
                      }}
                      onClose={() => {
                        session.clearFailure();
                        session.clearJob();
                        setScreen(hasScore ? "scoreReady" : "audioReady");
                      }}
                    />
                  }
                  scoreDocument={scoreDocument}
                  pitch={pitch}
                  initialViewMode={settings.scoreInitialView}
                  followPlayback={settings.followPlayback}
                  onInspectorChange={setInspectorModel}
                  onScoreStateChange={setScoreState}
                  scoreControllerRef={(c) => {
                    scoreCtlRef.current = c;
                  }}
                  announce={setStatusMessage}
                  transport={
                    mediaLive && transportSnap
                      ? {
                          isPlaying: transportSnap.status === "playing",
                          positionSec: transportSnap.time,
                          rate: transportSnap.rate,
                        }
                      : null
                  }
                  sourceControl={
                    // UI-050 元音源を再生 — real audio clock when a source is
                    // loaded; the score clock covers fixture/dev playback.
                    mediaLive
                      ? {
                          seekTo: (s: number) =>
                            void transport.seek(s).catch(() => undefined),
                          play: () =>
                            void transport.play().catch(() => undefined),
                          setLoop: (r) => transport.setLoop(r),
                        }
                        : null
                  }
                  onRhythmEdit={applyRhythmEdit}
                />
                {propertiesVisible ? (
                  <PropertiesPanel
                    content={inspector}
                    model={inspectorModel}
                    pitch={pitch}
                    width={layout.propertiesWidth}
                    min={layout.propertiesMin}
                    max={layout.propertiesMax}
                    overlay={layout.breakpoint === "compact"}
                    onResize={layout.requestPropertiesWidth}
                    onReset={layout.resetPropertiesWidth}
                    onClose={closeProperties}
                    onTempoChange={(bpm) =>
                      scoreCtlRef.current?.setTempo?.(bpm)
                    }
                    onMeterChange={(b, u) =>
                      scoreCtlRef.current?.setMeter?.(b, u)
                    }
                  />
                ) : null}
              </div>
              {regions.transport ? (
                <TransportBar
                  commands={commands}
                  live={
                    transportSnap && transportSnap.status !== "empty"
                      ? {
                          isPlaying: transportSnap.status === "playing",
                          positionSec: transportSnap.time,
                          durationSec: transportSnap.duration,
                          rate: transportSnap.rate,
                          muted: transportSnap.muted,
                        }
                      : undefined
                  }
                  onCycleRate={() => {
                    const idx = SUPPORTED_RATES.findIndex(
                      (r) => r === transportSnap?.rate,
                    );
                    const next =
                      SUPPORTED_RATES[(idx + 1) % SUPPORTED_RATES.length] ?? 1;
                    transport.setRate(next);
                  }}
                  timeLabel={
                    !mediaLive && scoreState
                      ? `${formatScoreTimecode(scoreState.positionMs)} / ${formatScoreTimecode(scoreState.durationMs)}`
                      : undefined
                  }
                  followEnabled={scoreState?.followEnabled}
                  followSuspended={scoreState?.followSuspended}
                  onToggleFollow={() => {
                    const c = scoreCtlRef.current;
                    if (!c) return;
                    if (scoreState?.followSuspended) c.resumeFollow();
                    else c.setFollowEnabled(!(scoreState?.followEnabled ?? true));
                  }}
                  auditionEnabled={scoreState?.auditionEnabled}
                  loopArmed={
                    transportSnap?.loop != null ||
                    (scoreState?.loopEnabled ?? false)
                  }
                />
              ) : null}
            </>
          )}
          <StatusBar
            message={statusMessage}
            detail={shellDetail}
            engineStatus={engineStatusText(sessionSnap.engine)}
          />
          {/* Re-import failure over a live workspace (§20): the audio session
              is kept, the failure surfaces as a dialog — never a dead end. */}
          {/* #76: 録音は現在の音源(と楽譜)を置き換えるため、開始前に確認。
              alert 型 = 破壊的操作の確認(JAPANESE_UI_COPY §8)。 */}
          <HsDialog
            open={pendingCapture !== null}
            modalType="alert"
            title={ja.capture.replaceTitle}
            onOpenChange={(open) => {
              if (!open) setPendingCapture(null);
            }}
            actions={
              <>
                <HsButton variant="danger" onClick={confirmCapture}>
                  {ja.capture.replaceConfirm}
                </HsButton>
                <HsButton
                  variant="secondary"
                  onClick={() => setPendingCapture(null)}
                >
                  {ja.capture.replaceCancel}
                </HsButton>
              </>
            }
          >
            <p style={{ margin: 0 }}>
              {scoreDocument
                ? ja.capture.replaceBodyWithScore
                : ja.capture.replaceBody}
            </p>
          </HsDialog>
          {importState.audio && importState.issue
            ? (() => {
                const copy = issueCopy(importState.issue);
                return (
                  <HsDialog
                    open
                    title={copy.title}
                    onOpenChange={(open) => {
                      if (!open) importer.dismiss();
                    }}
                    actions={
                      <>
                        <HsButton
                          variant="primary"
                          onClick={() => {
                            importer.dismiss();
                            void importer.openViaDialog();
                          }}
                        >
                          {ja.import.errors.chooseAnother}
                        </HsButton>
                        <HsButton
                          variant="secondary"
                          onClick={() => importer.dismiss()}
                        >
                          {ja.import.errors.close}
                        </HsButton>
                      </>
                    }
                  >
                    <p style={{ margin: 0 }}>
                      {copy.fileName ? `${copy.fileName} — ` : ""}
                      {copy.body}
                    </p>
                  </HsDialog>
                );
              })()
            : null}
          {/* UI-060 secondary surfaces — modals over the shell, never a
              workspace mode. Recovery paths deep-link into 設定/診断情報. */}
          <ExportDialog
            open={exportOpen}
            onOpenChange={setExportOpen}
            port={exportPort}
            defaultDestination={settings.defaultExportDir}
            toolOverrides={toolOverrides}
            onOpenSettings={(category) => {
              setSettingsFocus(category);
              setView("settings");
            }}
            onOpenDiagnostics={() => setDiagnosticsOpen(true)}
            onAnnounce={setStatusMessage}
          />
          <DiagnosticsSheet
            open={diagnosticsOpen}
            onOpenChange={setDiagnosticsOpen}
            port={diagnosticsPort}
            toolOverrides={toolOverrides}
            onAnnounce={setStatusMessage}
          />
          {/* #130 (spec 14): quantization settings on the finished
              score — seeded from the canonical payload's stored
              quantizationSettings; apply goes through the undoable
              score.edit path on the workspace controller. */}
          <RequantizeDialog
            open={requantizeOpen}
            seed={
              requantizeOpen
                ? requantizeSeed(scoreDocument?.canonicalDocument?.())
                : null
            }
            onOpenChange={setRequantizeOpen}
            onApply={(overrides) =>
              scoreCtlRef.current?.requantize?.(overrides)
            }
          />
        </AppShell>
      )}
    </FluentProvider>
  );
}

/**
 * Built-in command definitions (docs/GUI_UX_SPEC.md §7, §9, §14, §15, §22).
 *
 * This is the single source of truth: command bar buttons, menus, a future
 * command palette and the keyboard dispatcher all consume this list —
 * components never define their own shortcut handlers.
 *
 * Shortcut table (issue UI-012 / spec §9, §15, §22):
 *   Ctrl+O          open audio          F6 / Shift+F6   region cycle
 *   Space / K       play-pause          Ctrl+Z          undo
 *   Shift+Space     stop                Ctrl+Shift+Z    redo
 *   J / L           jump back/forward   Ctrl+E          export
 *   Home / End      start/end           Ctrl++ Ctrl+-   score zoom
 *   Ctrl+L          loop toggle         Ctrl+0          zoom to width
 *   Ctrl+1 / Ctrl+2 concert / F-horn    Esc             clear selection
 *
 * UI-050 review workspace (§12 — active while reviewOpen; the P4-validated
 * key set, so ← → are owned by issue navigation until per-note arrow
 * navigation lands and must share them through one command):
 *   ← / →           previous/next issue Alt+↑ / Alt+↓  pitch ±1 semitone
 *   R               replay source       Delete          delete/restore note
 *   O / Shift+O     accept / dismiss    Esc             exit review
 */

import { ja } from "../strings/ja";
import type { Command, CommandSnapshot } from "./types";

const hasAudio = (s: CommandSnapshot) => s.hasAudio;
const hasScore = (s: CommandSnapshot) => s.hasScore;
const canEditScore = (s: CommandSnapshot) => s.hasScore && !s.isTranscribing;

/**
 * All built-in commands. Order is the canonical listing order (command
 * palette / docs); `section` groups them for menus.
 */
export function createCommandDefinitions(): readonly Command[] {
  return [
    // ---- file ----
    {
      id: "file.openAudio",
      title: ja.commands.openAudio,
      section: "file",
      shortcuts: ["Ctrl+O"],
      // 録音中に別の音源を開くと、完了した録音が取り込み先を失って
      // 黙って上書きする — 録音中は無効化する。
      isEnabled: (s) => !s.isRecording,
      run: (ctx) => ctx.openAudio(),
    },

    // ---- score ----
    {
      id: "score.transcribe",
      title: ja.commands.transcribe,
      section: "score",
      // §5: rewriting the canonical score mid-transcription is forbidden.
      // 録音中は音声ソースが確定していないので採譜を始めさせない。
      isEnabled: (s) => s.hasAudio && !s.isTranscribing && !s.isRecording,
      run: (ctx) => ctx.transcribe(),
    },
    {
      id: "score.retranscribe",
      title: ja.commands.retranscribe,
      section: "score",
      // Same action as 採譜 once a score exists; the command bar relabels.
      isEnabled: (s) => s.hasScore && !s.isTranscribing && !s.isRecording,
      isVisible: (s) => s.hasScore,
      run: (ctx) => ctx.transcribe(),
    },
    {
      id: "score.cancelTranscription",
      title: ja.commands.cancelTranscription,
      section: "score",
      // §5/§27: cooperative job.cancel — only meaningful while a job is
      // in flight. Deliberately no shortcut: Esc must never silently
      // cancel a running transcription.
      isEnabled: (s) => s.isTranscribing,
      isVisible: (s) => s.isTranscribing,
      run: (ctx) => ctx.cancelTranscription?.(),
    },
    {
      id: "score.zoomIn",
      title: ja.commands.zoomScoreIn,
      section: "score",
      // "+" needs Shift on US/JIS layouts; "Ctrl+=" is the unshifted twin.
      // The numpad "+" also arrives as key "+" so no extra binding is needed.
      shortcuts: ["Ctrl+=", "Ctrl++"],
      isEnabled: canEditScore,
      run: (ctx) => ctx.zoomScoreIn(),
    },
    {
      id: "score.zoomOut",
      title: ja.commands.zoomScoreOut,
      section: "score",
      shortcuts: ["Ctrl+-"],
      isEnabled: canEditScore,
      run: (ctx) => ctx.zoomScoreOut(),
    },
    {
      id: "score.zoomFit",
      title: ja.commands.zoomScoreFit,
      section: "score",
      shortcuts: ["Ctrl+0"],
      isEnabled: canEditScore,
      run: (ctx) => ctx.zoomScoreFit(),
    },

    // ---- transport (§9) ----
    {
      id: "transport.playPause",
      title: ja.commands.playPause,
      section: "transport",
      shortcuts: ["Space", "K"],
      isEnabled: hasAudio,
      run: (ctx) => ctx.togglePlayPause(),
    },
    {
      id: "transport.stop",
      title: ja.commands.stop,
      section: "transport",
      shortcuts: ["Shift+Space"],
      isEnabled: hasAudio,
      run: (ctx) => ctx.stop(),
    },
    {
      id: "transport.jumpBack",
      title: ja.commands.jumpBack,
      section: "transport",
      shortcuts: ["J"],
      allowRepeat: true, // holding J/L scrubs, like video editors
      isEnabled: hasAudio,
      run: (ctx) => ctx.jumpBack(),
    },
    {
      id: "transport.jumpForward",
      title: ja.commands.jumpForward,
      section: "transport",
      shortcuts: ["L"],
      allowRepeat: true,
      isEnabled: hasAudio,
      run: (ctx) => ctx.jumpForward(),
    },
    {
      id: "transport.seekStart",
      title: ja.commands.seekStart,
      section: "transport",
      shortcuts: ["Home"],
      isEnabled: hasAudio,
      run: (ctx) => ctx.seekToStart(),
    },
    {
      id: "transport.seekEnd",
      title: ja.commands.seekEnd,
      section: "transport",
      shortcuts: ["End"],
      isEnabled: hasAudio,
      run: (ctx) => ctx.seekToEnd(),
    },
    {
      id: "transport.toggleLoop",
      title: ja.commands.toggleLoop,
      section: "transport",
      shortcuts: ["Ctrl+L"],
      isEnabled: hasAudio,
      run: (ctx) => ctx.toggleLoop(),
    },
    {
      id: "transport.toggleAudition",
      title: ja.commands.toggleAudition,
      shortcuts: ["P"],
      section: "transport",
      // 楽譜の演奏はスコアがある時だけ意味を持つ。録音中は鳴らさない
      // (#72): ループバック録音に演奏音が混入する + マイク録音でも
      // スピーカー音を拾うため。
      isEnabled: (s) => hasScore(s) && !s.isRecording,
      run: (ctx) => ctx.toggleScoreAudition?.(),
    },
    {
      id: "transport.toggleSourceMute",
      title: ja.commands.toggleSourceMute,
      section: "transport",
      // #72: 元音源だけをミュートして楽譜の演奏を確認する用途。
      // ミュートはメディア要素の属性なので録音中でも有効(録音対象の
      // ループバック音は止まらない)が、混乱を避け録音中も許可する。
      isEnabled: hasAudio,
      run: (ctx) => ctx.toggleSourceMute?.(),
    },

    // ---- capture (FEAT-001 #60) ----
    {
      id: "media.captureSystemAudio",
      title: ja.commands.captureSystemAudio,
      section: "file",
      // 録音は audio 無しでも始められる(結果が新しい audio になる)。
      isEnabled: (s) => !s.isTranscribing && !s.isRecording,
      run: (ctx) => ctx.captureSystemAudio?.(),
    },
    {
      id: "media.captureMicrophone",
      title: ja.commands.captureMicrophone,
      section: "file",
      isEnabled: (s) => !s.isTranscribing && !s.isRecording,
      run: (ctx) => ctx.captureMicrophone?.(),
    },
    {
      id: "media.stopCapture",
      title: ja.commands.stopCapture,
      section: "file",
      isEnabled: (s) => s.isRecording,
      isVisible: (s) => s.isRecording,
      run: (ctx) => ctx.stopCapture?.(),
    },
    {
      id: "media.cancelCapture",
      title: ja.commands.cancelCapture,
      section: "file",
      isEnabled: (s) => s.isRecording,
      isVisible: (s) => s.isRecording,
      run: (ctx) => ctx.cancelCapture?.(),
    },
    {
      // #80: 停止/再開は別コマンド(表示は録音中のみ)。
      id: "media.pauseCapture",
      title: ja.commands.pauseCapture,
      section: "file",
      isEnabled: (s) => s.isRecording && !s.isRecordingPaused,
      isVisible: (s) => s.isRecording,
      run: (ctx) => ctx.pauseCapture?.(),
    },
    {
      id: "media.resumeCapture",
      title: ja.commands.resumeCapture,
      section: "file",
      isEnabled: (s) => s.isRecording && s.isRecordingPaused,
      isVisible: (s) => s.isRecording,
      run: (ctx) => ctx.resumeCapture?.(),
    },

    // ---- view (§7: explicit pair, not a toggle) ----
    {
      id: "view.concertPitch",
      title: ja.commands.concertPitch,
      section: "view",
      shortcuts: ["Ctrl+1"],
      run: (ctx) => ctx.setPitchView("concert"),
    },
    {
      id: "view.hornF",
      title: ja.commands.hornF,
      section: "view",
      shortcuts: ["Ctrl+2"],
      run: (ctx) => ctx.setPitchView("hornF"),
    },

    // ---- review (§12, UI-050 keyboard-first flow) ----
    {
      id: "review.open",
      title: ja.commands.openReview,
      section: "review",
      isEnabled: (s) => s.hasScore && s.reviewCount > 0,
      isVisible: (s) => s.hasScore && s.reviewCount > 0,
      run: (ctx) => ctx.openReview(),
    },
    {
      id: "review.next",
      title: ja.commands.reviewNext,
      section: "review",
      // §12 header has a 次へ button too — the arrow keys keep review
      // processing menu-free (acceptance: 20 items without menus).
      shortcuts: ["ArrowRight"],
      // #114: shared with score.selectNext - mutually exclusive by
      // reviewOpen; the dispatcher picks the enabled one.
      shareShortcut: true,
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.reviewNext(),
    },
    {
      id: "review.previous",
      title: ja.commands.reviewPrevious,
      section: "review",
      shortcuts: ["ArrowLeft"],
      shareShortcut: true, // shared with score.selectPrevious (#114)
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.reviewPrevious(),
    },
    {
      id: "review.playSource",
      title: ja.commands.reviewPlaySource,
      section: "review",
      shortcuts: ["R"],
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.reviewPlaySource?.(),
    },
    {
      id: "review.accept",
      title: ja.commands.reviewAccept,
      section: "review",
      shortcuts: ["O"],
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.reviewAccept?.(),
    },
    {
      id: "review.dismiss",
      title: ja.commands.reviewDismiss,
      section: "review",
      shortcuts: ["Shift+O"],
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.reviewDismiss?.(),
    },
    {
      id: "review.pitchUp",
      title: ja.commands.reviewPitchUp,
      section: "review",
      shortcuts: ["Alt+ArrowUp"],
      shareShortcut: true, // shared with score.pitchUp (#114)
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.reviewPitchUp?.(),
    },
    {
      id: "review.pitchDown",
      title: ja.commands.reviewPitchDown,
      section: "review",
      shortcuts: ["Alt+ArrowDown"],
      shareShortcut: true, // shared with score.pitchDown (#114)
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.reviewPitchDown?.(),
    },
    {
      id: "review.deleteOrRestore",
      title: ja.commands.reviewDeleteOrRestore,
      section: "review",
      shortcuts: ["Delete", "Backspace"],
      shareShortcut: true, // shared with score.toggleDeleted (#114)
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.reviewDeleteOrRestore?.(),
    },
    {
      id: "review.exit",
      title: ja.commands.reviewExit,
      section: "review",
      // Esc is bound to edit.clearSelection, which exits review first —
      // this command exists so button/menu surfaces share one label.
      isEnabled: (s) => s.reviewOpen,
      isVisible: (s) => s.reviewOpen,
      run: (ctx) => ctx.exitReview?.(),
    },

    // ---- score note navigation + edits (#114, spec 10/13) ----
    // Arrow keys are shared with the review workspace: these stay
    // disabled while review is open so review.next/previous own them.
    {
      id: "score.selectNext",
      title: ja.commands.selectNextNote,
      section: "score",
      shortcuts: ["ArrowRight"],
      shareShortcut: true, // shared with review.next (#114)
      isEnabled: (s) => s.hasScore && !s.reviewOpen,
      run: (ctx) => ctx.selectAdjacentNote?.(1),
    },
    {
      id: "score.selectPrevious",
      title: ja.commands.selectPreviousNote,
      section: "score",
      shortcuts: ["ArrowLeft"],
      shareShortcut: true, // shared with review.previous (#114)
      isEnabled: (s) => s.hasScore && !s.reviewOpen,
      run: (ctx) => ctx.selectAdjacentNote?.(-1),
    },
    {
      id: "score.pitchUp",
      title: ja.commands.notePitchUp,
      section: "score",
      shortcuts: ["Alt+ArrowUp"],
      shareShortcut: true, // shared with review.pitchUp (#114)
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.editSelectedPitch?.(1),
    },
    {
      id: "score.pitchDown",
      title: ja.commands.notePitchDown,
      section: "score",
      shortcuts: ["Alt+ArrowDown"],
      shareShortcut: true, // shared with review.pitchDown (#114)
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.editSelectedPitch?.(-1),
    },
    {
      id: "score.toggleDeleted",
      title: ja.commands.noteToggleDeleted,
      section: "score",
      shortcuts: ["Delete", "Backspace"],
      shareShortcut: true, // shared with review.deleteOrRestore (#114)
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.toggleSelectedDeleted?.(),
    },
    {
      id: "score.toggleEnharmonic",
      title: ja.commands.noteEnharmonic,
      section: "score",
      shortcuts: ["E"],
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.toggleSelectedEnharmonic?.(),
    },
    {
      // #115 (spec 13): rhythm edits need the engine (score.edit), so
      // they live behind the same hasScore+selection gate; the workspace
      // announces honestly when the document cannot take them (fixture)
      // or the engine rejects the edit (span does not fit, no tie
      // partner, ...).
      id: "score.noteLonger",
      title: ja.commands.noteLonger,
      section: "score",
      shortcuts: ["Ctrl+Shift+ArrowUp"],
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.noteDurationScale?.(1),
    },
    {
      id: "score.noteShorter",
      title: ja.commands.noteShorter,
      section: "score",
      shortcuts: ["Ctrl+Shift+ArrowDown"],
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.noteDurationScale?.(-1),
    },
    {
      id: "score.noteShiftLeft",
      title: ja.commands.noteShiftLeft,
      section: "score",
      shortcuts: ["Ctrl+Shift+ArrowLeft"],
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.shiftSelectedOnset?.(-1),
    },
    {
      id: "score.noteShiftRight",
      title: ja.commands.noteShiftRight,
      section: "score",
      shortcuts: ["Ctrl+Shift+ArrowRight"],
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.shiftSelectedOnset?.(1),
    },
    {
      id: "score.toggleTie",
      title: ja.commands.noteToggleTie,
      section: "score",
      shortcuts: ["T"],
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.toggleSelectedTie?.(),
    },
    // #130 (spec 14): re-quantize under changed settings — menu-only
    // discoverability; the dialog owns the actual edit.
    {
      id: "score.requantize",
      title: ja.commands.requantize,
      section: "score",
      isEnabled: (s) => s.hasScore && !s.reviewOpen,
      run: (ctx) => ctx.openRequantizeDialog?.(),
    },
    // #131 (spec 13 post-MVP): split/merge — engine edits on the
    // selected note, same gate as the other rhythm edits.
    {
      id: "score.splitNote",
      title: ja.commands.noteSplit,
      section: "score",
      shortcuts: ["S"],
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.splitSelectedNote?.(),
    },
    {
      id: "score.mergeNotes",
      title: ja.commands.noteMerge,
      section: "score",
      shortcuts: ["M"],
      isEnabled: (s) => s.hasScore && s.hasSelection && !s.reviewOpen,
      run: (ctx) => ctx.mergeSelectedNotes?.(),
    },

    // ---- edit (§14: every fix is a command) ----
    {
      id: "edit.undo",
      title: ja.commands.undo,
      section: "edit",
      shortcuts: ["Ctrl+Z"],
      isEnabled: (s) => s.canUndo,
      run: (ctx) => ctx.undo(),
    },
    {
      id: "edit.redo",
      title: ja.commands.redo,
      section: "edit",
      shortcuts: ["Ctrl+Shift+Z"],
      isEnabled: (s) => s.canRedo,
      run: (ctx) => ctx.redo(),
    },
    {
      id: "edit.clearSelection",
      title: ja.commands.clearSelection,
      section: "edit",
      shortcuts: ["Escape"],
      // Esc exits the review workspace before it clears a selection (§12
      // review exit, controller.clearSelection owns the order) — so it
      // must stay enabled with the review bar up even when nothing is
      // selected (e.g. all issues resolved). #113: a waveform range
      // selection (AUDIO_READY) is cleared first (spec 8 Esc → 選択解除).
      isEnabled: (s) =>
        s.hasSelection || s.reviewOpen || s.hasWaveformSelection,
      run: (ctx, s) => {
        if (s.hasWaveformSelection) ctx.clearWaveformSelection?.();
        else ctx.clearSelection();
      },
    },

    // ---- export ----
    {
      id: "export.open",
      title: ja.commands.export,
      section: "export",
      shortcuts: ["Ctrl+E"],
      isEnabled: hasScore,
      run: (ctx) => ctx.openExport(),
    },
    {
      id: "export.openInMuseScore",
      title: ja.commands.openInMuseScore,
      section: "export",
      // No shortcut: an app-launch action stays menu-only (§13).
      isEnabled: hasScore,
      run: (ctx) => ctx.openInMuseScore?.(),
    },

    // ---- project save (#100) ----
    {
      id: "project.save",
      title: ja.commands.saveProject,
      section: "file",
      shortcuts: ["Ctrl+S"],
      isEnabled: (s) => s.hasScore && !s.isTranscribing,
      run: (ctx) => ctx.saveProject?.(),
    },

    // ---- navigation / focus (§22: F6 cycles the major regions) ----
    {
      id: "nav.nextRegion",
      title: ja.commands.nextRegion,
      section: "nav",
      shortcuts: ["F6"],
      run: (ctx) => ctx.focusNextRegion(),
    },
    {
      id: "nav.previousRegion",
      title: ja.commands.previousRegion,
      section: "nav",
      shortcuts: ["Shift+F6"],
      run: (ctx) => ctx.focusPreviousRegion(),
    },

    // ---- app ----
    {
      id: "app.settings",
      title: ja.commands.settings,
      section: "app",
      run: (ctx) => ctx.openSettings(),
    },
    {
      id: "app.diagnostics",
      title: ja.commands.diagnostics,
      section: "app",
      run: (ctx) => ctx.openDiagnostics(),
    },
  ];
}

/**
 * Command model types (docs/GUI_UX_SPEC.md §23).
 *
 * A Command is a *stateless* description: predicates receive a
 * CommandSnapshot so the same definitions can be evaluated for menus,
 * keyboard dispatch, palette listing and tests without re-registering.
 */

/** Pitch display modes (GUI_UX_SPEC §7). Kept literal here so the command
 *  layer does not depend on a component file. */
export type PitchViewSetting = "concert" | "hornF";

/** Top-level screens that gate command availability. */
export type AppView = "workspace" | "settings";

/** Grouping for menus / command palette / docs. */
export type CommandSection =
  | "file"
  | "score"
  | "transport"
  | "view"
  | "review"
  | "edit"
  | "export"
  | "nav"
  | "app";

/**
 * Immutable read of the app state that command predicates evaluate.
 * The app builds one per render; the registry never stores it.
 */
export interface CommandSnapshot {
  /** A source audio file is loaded (GUI_UX_SPEC §4, AUDIO_READY+). */
  readonly hasAudio: boolean;
  /** A canonical score exists (SCORE_READY+). */
  readonly hasScore: boolean;
  /** Transcription is running — score-writing commands disable (§5). */
  readonly isTranscribing: boolean;
  /** Audio is currently playing (drives the play/pause affordance). */
  readonly isPlaying: boolean;
  /** Loop range playback is armed. */
  readonly loopEnabled: boolean;
  /** Current pitch display mode. */
  readonly pitch: PitchViewSetting;
  /** Undo/redo stacks (§14 — all edits are commands). */
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  /** A note/region is selected (gates Esc = clear selection). */
  readonly hasSelection: boolean;
  /** #113: a waveform range selection exists (AUDIO_READY). Esc clears
   *  this before any score selection (spec 8: Esc -> 選択解除). */
  readonly hasWaveformSelection: boolean;
  /** 要確認 workspace state. */
  readonly reviewOpen: boolean;
  readonly reviewCount: number;
  /** FEAT-001: a recording session is in progress (loopback/mic). */
  readonly isRecording: boolean;
  /** FEAT-001 (#80): the recording session is paused. */
  readonly isRecordingPaused: boolean;
  /** FEAT-001: score audition (auto-playback of the score) is on. */
  readonly auditionEnabled: boolean;
  /** Active top-level view. */
  readonly view: AppView;
}

/**
 * The services commands act on. The app supplies implementations; during
 * the spike most are stubs that announce via `announce` so every invocation
 * produces honest feedback in the (aria-live) status bar.
 */
export interface CommandContext {
  openAudio(): void;
  transcribe(): void;
  /**
   * Cooperative `job.cancel` (UI-040): requests cancellation of the
   * in-flight transcription; the job still ends in a terminal `cancelled`
   * event, so callers must not assume an instant stop. Optional so older
   * test contexts keep compiling — an absent implementation is a no-op.
   */
  cancelTranscription?(): void;
  togglePlayPause(): void;
  stop(): void;
  jumpBack(): void;
  jumpForward(): void;
  seekToStart(): void;
  seekToEnd(): void;
  toggleLoop(): void;
  /**
   * FEAT-001 (#60): PC再生音源/マイク録音と楽譜自動演奏。
   * Optional so older test contexts keep compiling.
   */
  captureSystemAudio?(): void;
  captureMicrophone?(): void;
  /** 録音中なら停止して取り込む / 録音していなければ何もしない。 */
  stopCapture?(): void;
  /** 録音を中止して破棄する。 */
  cancelCapture?(): void;
  /** 録音を一時停止する(#80)。 */
  pauseCapture?(): void;
  /** 一時停止した録音を再開する(#80)。 */
  resumeCapture?(): void;
  /** 楽譜の自動演奏トグル(スコアクロックに同期して発音)。 */
  toggleScoreAudition?(): void;
  /** 元音源のミュート切替(#72)。楽譜の演奏だけを聴く用途。 */
  toggleSourceMute?(): void;
  setPitchView(view: PitchViewSetting): void;
  openReview(): void;
  reviewNext(): void;
  reviewPrevious(): void;
  /**
   * UI-050 review-workspace actions (GUI_UX_SPEC §12). Optional like
   * `cancelTranscription` so leaner test contexts keep compiling — an
   * absent implementation is a no-op.
   */
  reviewAccept?(): void;
  reviewDismiss?(): void;
  reviewPlaySource?(): void;
  reviewPitchUp?(): void;
  reviewPitchDown?(): void;
  reviewDeleteOrRestore?(): void;
  exitReview?(): void;
  undo(): void;
  redo(): void;
  openExport(): void;
  /** §13 高度編集: open the live score in the MuseScore GUI (async —
   *  the implementation announces success/failure itself). Optional:
   *  absent = no-op. */
  openInMuseScore?(): void;
  /** #100: プロジェクトを保存 — opens the save-file picker and writes
   *  .hornscribe.json through the engine. Optional like the other
   *  late-binding commands; absent = no-op. */
  saveProject?(): void;
  zoomScoreIn(): void;
  zoomScoreOut(): void;
  zoomScoreFit(): void;
  clearSelection(): void;
  /** #114 (spec 10): select the previous/next note (score workspace). */
  selectAdjacentNote?(direction: 1 | -1): void;
  /** #114 (spec 13): semitone-shift / delete / respell the selected
   *  note outside the review workspace (undoable). */
  editSelectedPitch?(delta: number): void;
  toggleSelectedDeleted?(): void;
  toggleSelectedEnharmonic?(): void;
  /** #115 (spec 13): engine rhythm edits on the selected note —
   *  duration ladder (+1 = ×2, -1 = ÷2), onset shift by min-grid steps,
   *  tie/untie to the contiguous next same-pitch note. Async: the
   *  implementation announces success/failure itself. Optional so
   *  fixture/test contexts keep compiling — absent = no-op. */
  noteDurationScale?(power: number): void;
  shiftSelectedOnset?(steps: number): void;
  toggleSelectedTie?(): void;
  /** #130 (spec 14): open the quantization-settings dialog — the
   *  requantize edit itself is applied via the score controller. */
  openRequantizeDialog?(): void;
  /** #131 (spec 13 post-MVP): split/merge the selected note. */
  splitSelectedNote?(): void;
  mergeSelectedNotes?(): void;
  /** #113: Esc on a waveform selection (AUDIO_READY) - clears the range
   *  back to "all" (spec 8: Esc -> 選択解除). Optional: absent = no-op. */
  clearWaveformSelection?(): void;
  openSettings(): void;
  /** Opens the 診断情報 sheet (§19 — separated from the normal UI). */
  openDiagnostics(): void;
  /** F6 region navigation — implemented by focus/zones. */
  focusNextRegion(): void;
  focusPreviousRegion(): void;
  /**
   * Surface command feedback in the status area (role="status" is
   * aria-live, so Narrator users hear the result — UX_VALIDATION §11).
   */
  announce(message: string): void;
}

/**
 * A single invocable command — the unit the registry, command bar, menus,
 * palette and keyboard dispatcher all share (single source of truth).
 */
export interface Command {
  /** Stable dotted id, e.g. "transport.playPause". */
  readonly id: string;
  /**
   * Japanese title — the only UI language (UI_COPY_CONTRACT). This is what
   * buttons, menus, a palette and screen readers all announce.
   */
  readonly title: string;
  /** Optional longer Japanese description for palettes/menus. */
  readonly description?: string;
  readonly section: CommandSection;
  /**
   * Keyboard bindings in "Ctrl+Shift+Z" notation; whitespace separates
   * chords in a multi-step sequence. The first entry is the canonical
   * binding shown in tooltips / aria-keyshortcuts.
   */
  readonly shortcuts?: readonly string[];
  /**
   * #114: opt-in to sharing a chord with another command whose
   * `isEnabled` predicate is mutually exclusive (e.g. ArrowRight =
   * review.next while reviewing, score.selectNext otherwise). Every
   * command on the shared chord must set this flag; the dispatcher
   * activates the first *enabled* candidate.
   */
  readonly shareShortcut?: boolean;
  /**
   * May run against this snapshot. Default: enabled. Disabled commands are
   * non-executable everywhere — toolbar, menu AND shortcut (issue req:
   * "disabled commands remain non-executable via shortcut").
   */
  readonly isEnabled?: (snapshot: CommandSnapshot) => boolean;
  /**
   * Listed on command surfaces (palette/menus/overflow). Default: visible.
   * Hidden commands still run when enabled — e.g. 採譜し直す vs 採譜.
   */
  readonly isVisible?: (snapshot: CommandSnapshot) => boolean;
  /** May fire while a text field / IME host has focus. Default false. */
  readonly allowInTextInput?: boolean;
  /** May fire while a modal dialog/sheet owns focus. Default false. */
  readonly allowInModal?: boolean;
  /** Re-fires on key auto-repeat. Default false (no accidental toggles). */
  readonly allowRepeat?: boolean;
  /** Execute against live services. */
  readonly run: (ctx: CommandContext, snapshot: CommandSnapshot) => void;
}

import { Toolbar, ToolbarButton, Tooltip } from "@fluentui/react-components";
import {
  FolderOpen24Regular,
  Play24Regular,
  CheckmarkCircle24Regular,
  ArrowExportUp24Regular,
  Settings24Regular,
  MoreHorizontal24Regular,
  PanelRight24Regular,
  Wrench24Regular,
  Open24Regular,
  Mic24Regular,
  Speaker2Regular,
  Stop24Regular,
  Pause24Regular,
  Dismiss24Regular,
  ArrowUp24Regular,
  ArrowDown24Regular,
  ArrowLeft24Regular,
  ArrowRight24Regular,
  Link24Regular,
  MusicNote224Regular,
  TableCellsSplit24Regular,
  TableCellsMerge24Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import type { CommandSurface } from "../commands/registry";
import { HsMenu, type HsMenuItem } from "./primitives/Menu";
import { PitchSegmented, type PitchView } from "./PitchSegmented";
import {
  hasWorkspaceRegions,
  type ScreenState,
} from "../workspace/screen";
import type { CaptureState } from "../capture/controller";
import type {
  CaptureDeviceList,
  CaptureSource,
} from "../capture/types";
import { formatTimecode } from "../import/format";

/** 録音経過の短い表示(0:00 形式)。 */
function formatElapsed(seconds: number): string {
  return formatTimecode(seconds);
}

/** Tooltip text: Japanese title plus its canonical shortcut, e.g.
 *  「書き出し（Ctrl+E）」 — shortcut hinting is spec'd on §9 controls. */
function withShortcut(title: string, shortcut?: string): string {
  return shortcut ? `${title}（${shortcut}）` : title;
}

/**
 * Command bar (GUI_UX_SPEC §16, DESIGN_SYSTEM §10).
 * Left: project actions. Center: pitch selector. Right: 要確認/書き出し/設定/overflow.
 * Never scrolls; at <1600px secondary labels collapse to icon+tooltip
 * (§21), at <1200px 設定 moves into the overflow menu. The menu always
 * carries the properties show/close toggle so the panel stays reachable.
 *
 * EMPTY state (§3) hides every score/audio command — only 開く, 設定 and
 * the overflow menu render, so the empty surface stays free of score tools.
 *
 * Every action routes through the command surface (§23): enabled state,
 * Japanese label and shortcut all come from the registry, so the button,
 * the menu item and the keyboard binding can never disagree.
 */
export function CommandBar({
  commands,
  pitch,
  screen,
  reviewCount,
  compact,
  propertiesOpen,
  onToggleProperties,
  captureState,
  captureDevices,
  captureSelectedDevice,
  onSelectCaptureDevice,
  onCaptureMenuOpen,
}: {
  commands: CommandSurface;
  pitch: PitchView;
  screen: ScreenState;
  reviewCount: number;
  /** <1200px breakpoint — 設定 lives in the overflow menu instead. */
  compact: boolean;
  propertiesOpen: boolean;
  onToggleProperties(): void;
  /** FEAT-001 (#60): live capture state for the recording affordance. */
  captureState?: CaptureState | null;
  /** #73: 取り込みデバイス一覧(メニュー開時に最新化される)。 */
  captureDevices?: CaptureDeviceList | null;
  /** 選択中のデバイス ID(null = 既定)。 */
  captureSelectedDevice?(source: CaptureSource): string | null;
  onSelectCaptureDevice?(source: CaptureSource, id: string | null): void;
  /** メニューが開いた時にデバイス一覧を取り直す。 */
  onCaptureMenuOpen?(): void;
}) {
  // 採譜 ↔ 採譜し直す — same command slot, label follows score presence
  // (the registry hides retranscribe until a score exists).
  const transcribeId = "score.transcribe";
  const retranscribeId = "score.retranscribe";
  const transcribe = commands.isVisible(retranscribeId)
    ? retranscribeId
    : transcribeId;

  const onPitch = (v: PitchView) =>
    commands.invoke(v === "concert" ? "view.concertPitch" : "view.hornF");

  // EMPTY and the import error states (§3/§20) keep the command bar to
  // shell actions only — no score/audio commands without a live context.
  const loaded = hasWorkspaceRegions(screen);
  const hasScore =
    screen === "scoreReady" || screen === "reviewing" || screen === "exporting";
  const transcribeTooltip = hasScore
    ? ja.commandBar.retranscribeTooltip
    : ja.commandBar.transcribeTooltip;
  const reviewLabel =
    reviewCount > 0
      ? ja.commandBar.reviewWithCount.replace("{count}", String(reviewCount))
      : ja.commandBar.review;

  const overflowItems: HsMenuItem[] = [
    ...(compact
      ? [
          {
            key: "settings",
            label: commands.title("app.settings"),
            icon: <Settings24Regular />,
          } satisfies HsMenuItem,
        ]
      : []),
    {
      key: "properties",
      label: propertiesOpen ? ja.properties.close : ja.properties.show,
      icon: <PanelRight24Regular />,
    },
    // §13 高度編集: hand the live score to MuseScore (score only — the
    // item hides on import screens like the 書き出し button does).
    ...(hasScore
      ? [
          {
            key: "musescore",
            label: commands.title("export.openInMuseScore"),
            icon: <Open24Regular />,
            disabled: !commands.isEnabled("export.openInMuseScore"),
          } satisfies HsMenuItem,
        ]
      : []),
    // #115 (spec 13): per-note rhythm edits — menu-only discoverability;
    // the keyboard chords do the real work. Disabled without a note
    // selection (the command registry owns the gate).
    ...(hasScore
      ? [
          { key: "rhythm-divider", divider: true } satisfies HsMenuItem,
          {
            key: "note-longer",
            label: commands.title("score.noteLonger"),
            icon: <ArrowUp24Regular />,
            disabled: !commands.isEnabled("score.noteLonger"),
          } satisfies HsMenuItem,
          {
            key: "note-shorter",
            label: commands.title("score.noteShorter"),
            icon: <ArrowDown24Regular />,
            disabled: !commands.isEnabled("score.noteShorter"),
          } satisfies HsMenuItem,
          {
            key: "note-shift-left",
            label: commands.title("score.noteShiftLeft"),
            icon: <ArrowLeft24Regular />,
            disabled: !commands.isEnabled("score.noteShiftLeft"),
          } satisfies HsMenuItem,
          {
            key: "note-shift-right",
            label: commands.title("score.noteShiftRight"),
            icon: <ArrowRight24Regular />,
            disabled: !commands.isEnabled("score.noteShiftRight"),
          } satisfies HsMenuItem,
          {
            key: "note-tie",
            label: commands.title("score.toggleTie"),
            icon: <Link24Regular />,
            disabled: !commands.isEnabled("score.toggleTie"),
          } satisfies HsMenuItem,
          // #131 (spec 13 post-MVP): split/merge — same selection gate.
          {
            key: "note-split",
            label: commands.title("score.splitNote"),
            icon: <TableCellsSplit24Regular />,
            disabled: !commands.isEnabled("score.splitNote"),
          } satisfies HsMenuItem,
          {
            key: "note-merge",
            label: commands.title("score.mergeNotes"),
            icon: <TableCellsMerge24Regular />,
            disabled: !commands.isEnabled("score.mergeNotes"),
          } satisfies HsMenuItem,
          // #130 (spec 14): score-wide re-quantize — always enabled with
          // a score (no selection needed); opens the settings dialog.
          {
            key: "requantize",
            label: commands.title("score.requantize"),
            icon: <MusicNote224Regular />,
            disabled: !commands.isEnabled("score.requantize"),
          } satisfies HsMenuItem,
        ]
      : []),
    { key: "overflow-divider", divider: true },
    // §16: diagnostics lives in the overflow, never on the command bar.
    {
      key: "diagnostics",
      label: commands.title("app.diagnostics"),
      icon: <Wrench24Regular />,
    },
  ];

  // FEAT-001: capture menu lives next to 開く — sources of new audio.
  // #73: 各ソースの下にそのソースのデバイス選択を並べる。選択中は ✓。
  const deviceItems = (
    source: CaptureSource,
    devices: readonly { id: string; name: string; isDefault: boolean }[],
  ): HsMenuItem[] => {
    // デバイスが1台も無いソース(ブラウザ dev の loopback 等)は
    // セクション自体を出さない — 既定しか選べない行は誤解を招く。
    if (devices.length === 0) return [];
    const selected = captureSelectedDevice?.(source) ?? null;
    const sectionLabel =
      source === "loopback"
        ? ja.capture.loopbackDeviceLabel
        : ja.capture.microphoneDeviceLabel;
    const items: HsMenuItem[] = [
      { key: source + "-hdr", label: sectionLabel, disabled: true },
      {
        key: source + ":default",
        label:
          selected === null
            ? "\u2713 " + ja.capture.defaultDevice
            : ja.capture.defaultDevice,
      },
    ];
    for (const d of devices) {
      items.push({
        key: source + ":" + d.id,
        label: selected === d.id ? "\u2713 " + d.name : d.name,
      });
    }
    return items;
  };
  const captureMenuItems: HsMenuItem[] = [
    {
      key: "loopback",
      label: commands.title("media.captureSystemAudio"),
      icon: <Speaker2Regular />,
      disabled: !commands.isEnabled("media.captureSystemAudio"),
    },
    {
      key: "microphone",
      label: commands.title("media.captureMicrophone"),
      icon: <Mic24Regular />,
      disabled: !commands.isEnabled("media.captureMicrophone"),
    },
    // デバイスセクションは一覧が取れた時だけ出す(ブラウザ dev では
    // loopback は空、mic のみ)。両方空なら区切り線ごと出さない。
    ...(captureDevices &&
    (captureDevices.loopback.length > 0 ||
      captureDevices.microphone.length > 0)
      ? ([
          { key: "devices-divider", divider: true },
          ...deviceItems("loopback", captureDevices.loopback),
          ...deviceItems("microphone", captureDevices.microphone),
        ] satisfies HsMenuItem[])
      : []),
  ];
  const recording = captureState?.phase === "recording";
  const captureLabel =
    recording && captureState?.source === "loopback"
      ? ja.transport.recordingLoopbackLabel
      : recording
        ? ja.transport.recordingLabel
        : "取り込み";

  return (
    <Toolbar
      className="hs-commandbar"
      aria-label={ja.commandBar.regionLabel}
      data-hs-focus-zone="commandbar"
      tabIndex={-1}
    >
      <Tooltip content={ja.commandBar.openTooltip} relationship="label">
        <ToolbarButton
          icon={<FolderOpen24Regular />}
          disabled={!commands.isEnabled("file.openAudio")}
          aria-keyshortcuts="Control+O"
          onClick={() => commands.invoke("file.openAudio")}
        >
          <span className="hs-commandbar__label">{ja.commandBar.openLabel}</span>
        </ToolbarButton>
      </Tooltip>
      {loaded ? (
        <Tooltip content={transcribeTooltip} relationship="label">
          <ToolbarButton
            icon={<Play24Regular />}
            disabled={!commands.isEnabled(transcribe)}
            appearance="primary"
            onClick={() => commands.invoke(transcribe)}
          >
            <span className="hs-commandbar__label">
              {commands.title(transcribe)}
            </span>
          </ToolbarButton>
        </Tooltip>
      ) : null}

      {loaded ? <span className="hs-commandbar__spacer" /> : null}
      {loaded ? <PitchSegmented value={pitch} onChange={onPitch} /> : null}
      <span className="hs-commandbar__spacer" />

      {/* FEAT-001: 録音ソース — EMPTY/READY どちらでも新しい音源を取り込める。
          録音中は「停止して取り込む」「やめる」の 2 操作に切り替わる。 */}
      {!recording ? (
        <HsMenu
          trigger={
            <ToolbarButton icon={<Mic24Regular />} aria-label={captureLabel}>
              <span className="hs-commandbar__label">{captureLabel}</span>
            </ToolbarButton>
          }
          items={captureMenuItems}
          ariaLabel={captureLabel}
          onOpenChange={(open) => {
            if (open) onCaptureMenuOpen?.();
          }}
          onSelect={(key) => {
            if (key === "loopback") commands.invoke("media.captureSystemAudio");
            else if (key === "microphone") commands.invoke("media.captureMicrophone");
            else if (key === "loopback:default")
              onSelectCaptureDevice?.("loopback", null);
            else if (key === "microphone:default")
              onSelectCaptureDevice?.("microphone", null);
            else if (key.startsWith("loopback:"))
              onSelectCaptureDevice?.("loopback", key.slice("loopback:".length));
            else if (key.startsWith("microphone:"))
              onSelectCaptureDevice?.(
                "microphone",
                key.slice("microphone:".length),
              );
          }}
        />
      ) : (
        <>
          <Tooltip content={commands.title("media.stopCapture")} relationship="label">
            <ToolbarButton
              icon={<Stop24Regular />}
              appearance="primary"
              aria-keyshortcuts="Ctrl+Enter"
              onClick={() => commands.invoke("media.stopCapture")}
            >
              <span className="hs-commandbar__label">
                {commands.title("media.stopCapture")}
                {captureState?.elapsedSeconds != null
                  ? ` ${formatElapsed(captureState.elapsedSeconds)}`
                  : ""}
                {captureState?.paused ? ` — ${ja.capture.pausedLabel}` : ""}
              </span>
            </ToolbarButton>
          </Tooltip>
          {/* #80: 一時停止/再開 — paused 中はアイコンと対象コマンドが
              切り替わる。停止・中止は paused 中もそのまま使える。 */}
          {captureState?.paused ? (
            <Tooltip content={commands.title("media.resumeCapture")} relationship="label">
              <ToolbarButton
                icon={<Play24Regular />}
                aria-label={commands.title("media.resumeCapture")}
                onClick={() => commands.invoke("media.resumeCapture")}
              />
            </Tooltip>
          ) : (
            <Tooltip content={commands.title("media.pauseCapture")} relationship="label">
              <ToolbarButton
                icon={<Pause24Regular />}
                aria-label={commands.title("media.pauseCapture")}
                onClick={() => commands.invoke("media.pauseCapture")}
              />
            </Tooltip>
          )}
          <Tooltip content={commands.title("media.cancelCapture")} relationship="label">
            <ToolbarButton
              icon={<Dismiss24Regular />}
              onClick={() => commands.invoke("media.cancelCapture")}
            />
          </Tooltip>
        </>
      )}

      {loaded ? (
        <Tooltip content={reviewLabel} relationship="label">
          <ToolbarButton
            icon={<CheckmarkCircle24Regular />}
            disabled={!commands.isEnabled("review.open")}
            onClick={() => commands.invoke("review.open")}
          >
            <span className="hs-commandbar__label">{reviewLabel}</span>
          </ToolbarButton>
        </Tooltip>
      ) : null}
      {loaded ? (
        <Tooltip
          content={withShortcut(
            ja.commandBar.exportTooltip,
            commands.shortcutLabel("export.open"),
          )}
          relationship="label"
        >
          <ToolbarButton
            icon={<ArrowExportUp24Regular />}
            disabled={!commands.isEnabled("export.open")}
            aria-keyshortcuts="Control+E"
            onClick={() => commands.invoke("export.open")}
          >
            <span className="hs-commandbar__label">
              {commands.title("export.open")}
            </span>
          </ToolbarButton>
        </Tooltip>
      ) : null}
      {!compact && commands.isEnabled("app.settings") ? (
        <Tooltip
          content={commands.title("app.settings")}
          relationship="label"
        >
          <ToolbarButton
            icon={<Settings24Regular />}
            onClick={() => commands.invoke("app.settings")}
          />
        </Tooltip>
      ) : null}
      <HsMenu
        trigger={
          <ToolbarButton
            icon={<MoreHorizontal24Regular />}
            aria-label={ja.commandBar.overflow}
          />
        }
        items={overflowItems}
        ariaLabel={ja.commandBar.overflow}
        onSelect={(key) => {
          if (key === "settings") commands.invoke("app.settings");
          else if (key === "properties") onToggleProperties();
          else if (key === "musescore")
            commands.invoke("export.openInMuseScore");
          else if (key === "note-longer") commands.invoke("score.noteLonger");
          else if (key === "note-shorter") commands.invoke("score.noteShorter");
          else if (key === "note-shift-left")
            commands.invoke("score.noteShiftLeft");
          else if (key === "note-shift-right")
            commands.invoke("score.noteShiftRight");
          else if (key === "note-tie") commands.invoke("score.toggleTie");
          else if (key === "diagnostics") commands.invoke("app.diagnostics");
        }}
      />
    </Toolbar>
  );
}

/**
 * UI-030 — production score workspace (SCORE_READY+, GUI_UX_SPEC §6–§11).
 *
 * Verovio-based SVG rendering driven by a `ScoreDocumentPort` (fixture
 * adapter today; engine data slots in later). Responsibilities:
 *
 * - render MusicXML → SVG pages (inlined WASM, fully offline);
 * - note click → canonical `sn-*` selection → properties inspector;
 * - Concert ↔ F管ホルン switch preserving selection, transport position,
 *   loop, playback state, zoom and an equivalent viewport position
 *   (UI-005 verified semantics);
 * - playback hierarchy: caret → current-measure wash → active-note outline,
 *   all DOM-only marks — zero `renderToSVG` on the frame path;
 * - follow playback with manual-scroll suspension + explicit 追従を再開;
 * - review 要確認 markers (dotted cue, warning tint — never error red);
 * - zoom controls bound to the same methods the registry commands call.
 */
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { ja } from "../strings/ja";
import type { PitchViewSetting } from "../commands/types";
import type { ScoreDocumentPort } from "./document";
import { ScoreView } from "./ScoreView";
import {
  ACTIVE_CLASS,
  LOOP_CLASS,
  MEASURE_ACTIVE_CLASS,
  SELECTED_CLASS,
  buildElementIndex,
  clearCaret,
  drawCaret,
  markCanonical,
  markCanonicalSet,
  markMeasures,
  markReviewMarkers,
  measureElementOf,
  type ElementIndex,
} from "./domScore";
import { canonicalNoteIdFromMusicxml } from "./ids";
import {
  describeNote,
  notesByCanonical,
  notesByExportId,
  parseScoreDoc,
  type ParsedNote,
  type ScoreDoc,
} from "./scoreDoc";
import {
  getScoreRenderer,
  clampScoreZoom,
  SCORE_ZOOM_STEP_PCT,
  type RenderedPage,
  type ScoreRenderer,
  type ScoreViewMode,
} from "./verovio";
import {
  readScoreSessionView,
  writeScoreSessionView,
} from "../workspace/layout";
import {
  buildPlaybackTable,
  canonicalsInRange,
  segmentAt,
  type PlaybackTable,
} from "./playbackTable";
import { ScoreCursorClock, type ClockSnapshot, type TransportClock } from "./clock";
import { ScorePlaybackSynth } from "./playbackSynth";
import {
  allIssuesForCanonical,
  markedCanonicalIds,
  numEvidence,
  type ScoreReviewIssue,
} from "./review";
import { ReviewSession, type ReviewEdit } from "./reviewSession";
import { ReviewBar } from "./ReviewBar";
import {
  findCanonicalNote,
  formatFraction,
  scaleFraction,
  type RhythmEditInvoker,
  type RhythmEditOp,
} from "./rhythmEdits";
import {
  buildNoteInspector,
  buildScoreInspector,
  keyLabelJa,
  type InspectorCopy,
  type InspectorModel,
} from "./inspector";
import type { ScoreWorkspaceController, ScoreWorkspaceState } from "./controller";
import { SegmentedControl } from "../components/primitives/SegmentedControl";
import { HsButton } from "../components/primitives/Button";

interface Selection {
  exportId: string;
  canonicalId: string | null;
}

interface Props {
  document: ScoreDocumentPort;
  pitch: PitchViewSetting;
  onInspectorChange(model: InspectorModel): void;
  onStateChange?(state: ScoreWorkspaceState): void;
  controllerRef?(controller: ScoreWorkspaceController | null): void;
  announce(message: string): void;
  /** [UI-020 handoff] live media-transport mirror. When present the score
   *  clock follows it — the media element is the one audio clock (UI-005
   *  "one clock" contract); when absent (no source loaded, dev/fixture
   *  playback) the score's own ScoreCursorClock is the transport. */
  transport?: {
    readonly isPlaying: boolean;
    readonly positionSec: number;
    readonly rate?: number;
  } | null;
  /** [UI-050] 元音源を再生 / jump-to-issue: drive the real media transport
   *  (seek + A-B loop on the issue's source range) when audio is loaded.
   *  When absent, the score clock plays the range so the passage is still
   *  indicated on the score (dev/fixture playback). */
  sourceControl?: {
    seekTo(sec: number): void;
    play(): void;
    setLoop(range: { start: number; end: number } | null): void;
  } | null;
  /** 設定→楽譜 初期表示 — seeds viewMode on mount (document key
   *  remounts per revision, so this is a per-score default). */
  initialViewMode?: ScoreViewMode;
  /** 設定→再生 再生位置を追従 — seeds the follow toggle. */
  followPlayback?: boolean;
  /** #115 (spec 13): engine score.edit invoker — absent for fixture/dev
   *  documents, where rhythm edits announce as unavailable instead of
   *  pretending to work. */
  onRhythmEdit?: RhythmEditInvoker;
}

const EMPTY_SET: ReadonlySet<string> = new Set<string>();

function sameSet(a: ReadonlySet<string>, b: ReadonlySet<string>): boolean {
  if (a.size !== b.size) return false;
  for (const v of a) if (!b.has(v)) return false;
  return true;
}

/** Reason-code → copy deck. `ReviewReason` is forward-compatible
 *  (`string & {}`), so index through a plain record — unknown engine codes
 *  land on `other`. */
const REASON_DECK: Record<string, { readonly title: string; readonly detail: string }> =
  ja.reviewReasons;

/** Inspector copy — bound to ja.ts so Japanese text stays in one place. */
function inspectorCopy(): InspectorCopy {
  const j = ja.inspector;
  return {
    review: {
      // `?? other`: engine reason codes may be newer than this UI's copy
      // deck — the issue stays visible with generic copy (sidecar/review.ts
      // uses the same fallback policy).
      reasonTitle: (r) => (REASON_DECK[r] ?? ja.reviewReasons.other).title,
      reasonDetail: (issue: ScoreReviewIssue) => {
        // #85 voices texture: surface the split counts the engine put in
        // evidence — "kept N notes as a second voice, dropped M beyond
        // two voices" — instead of the generic overlap copy.
        if (issue.reason === "overlapping_candidates") {
          const second = numEvidence(issue, "secondVoiceNotes");
          const dropped = numEvidence(issue, "droppedBeyondVoices");
          if (second != null || dropped != null) {
            return ja.reviewEvidence.secondVoice(second ?? 0, dropped ?? 0);
          }
          const merged = numEvidence(issue, "polyphonicOverlaps");
          if (merged != null) {
            return ja.reviewEvidence.mergedOverlaps(merged);
          }
        }
        return (REASON_DECK[issue.reason] ?? ja.reviewReasons.other).detail;
      },
      severityLabel: (s) => ja.reviewSeverity[s] ?? ja.reviewSeverity.info,
      statusLabel: (s) => ja.reviewStatus[s] ?? ja.reviewStatus.open,
    },
    measure: (n) => ja.scoreView.measureNth(n),
    scoreSeconds: (sec) => j.scoreSeconds(sec),
    tieFragments: (n) => j.tieFragments(n),
    tempo: (bpm) => j.tempoLabel(bpm),
    measureCount: (n) => j.measureCountLabel(n),
    noteCount: (n) => j.noteCountLabel(n),
    openIssues: (n) => j.openIssuesLabel(n),
    key: (fifths) => j.keyLabel(keyLabelJa(fifths)),
  };
}

export function ScoreReadyWorkspace({
  document: scoreDoc,
  pitch,
  initialViewMode = "continuous",
  followPlayback = true,
  onInspectorChange,
  onStateChange,
  controllerRef,
  announce,
  transport,
  sourceControl = null,
  onRhythmEdit,
}: Props) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const rendererRef = useRef<ScoreRenderer | null>(null);
  const indexRef = useRef<ElementIndex | null>(null);
  const clockRef = useRef<TransportClock | null>(null);
  const tableRef = useRef<PlaybackTable | null>(null);

  const [pages, setPages] = useState<RenderedPage[]>([]);
  /* §26: restore the previous session's score view (zoom + mode); the
   * settings "initial view" only applies when no session state exists. */
  const sessionViewRef = useRef(readScoreSessionView());
  const [viewMode, setViewMode] = useState<ScoreViewMode>(
    sessionViewRef.current.viewMode ?? initialViewMode,
  );
  const [currentPage, setCurrentPage] = useState(1);
  const [zoom, setZoom] = useState(
    sessionViewRef.current.zoomPct ?? 100,
  );
  const [selection, setSelection] = useState<Selection | null>(null);
  const [loading, setLoading] = useState(true);
  const [renderError, setRenderError] = useState(false);
  const [initError, setInitError] = useState<string | null>(null);
  const [followEnabled, setFollowEnabled] = useState(followPlayback);
  const [followSuspended, setFollowSuspended] = useState(false);
  const [reviewOpen, setReviewOpen] = useState(false);
  const [reviewIndex, setReviewIndex] = useState(0);
  const [clockSnap, setClockSnap] = useState<ClockSnapshot>({
    positionMs: 0,
    durationMs: 0,
    isPlaying: false,
    rate: 1,
    loop: null,
  });
  // FEAT-001: score audition engine. Lazily created when the user turns
  // the audition toggle on; synced with the score clock below.
  const synthRef = useRef<ScorePlaybackSynth | null>(null);
  const [auditionEnabled, setAuditionEnabled] = useState(false);
  const auditionRef = useRef(false);

  // Parsed presentations — identical canonical ids, different spelling.
  const docsRef = useRef<{
    concert: ScoreDoc;
    horn: ScoreDoc;
    concertByCanonical: Map<string, ParsedNote[]>;
    hornByCanonical: Map<string, ParsedNote[]>;
    concertByExport: Map<string, ParsedNote>;
    hornByExport: Map<string, ParsedNote>;
  } | null>(null);

  // Refs mirrored so the rAF pump / layout effect always see fresh values.
  const selectionRef = useRef<Selection | null>(null);
  const activeRef = useRef<ReadonlySet<string>>(EMPTY_SET);
  const loopCanonicalsRef = useRef<ReadonlySet<string>>(EMPTY_SET);
  const followRef = useRef(true);
  const suspendedRef = useRef(false);
  const zoomRef = useRef(sessionViewRef.current.zoomPct ?? 100);
  const viewModeRef = useRef<ScoreViewMode>(
    sessionViewRef.current.viewMode ?? initialViewMode,
  );
  const currentPageRef = useRef(1);
  const pitchRef = useRef(pitch);
  /** The presentation actually loaded into Verovio — compared against the
   *  `pitch` prop to detect a real view switch (the prop ref alone is
   *  updated every render and would mask the change). */
  const renderedPitchRef = useRef<PitchViewSetting | null>(null);
  const reviewIndexRef = useRef(0);
  const reviewOpenRef = useRef(false);
  const pendingScrollRef = useRef<{ ratio: number } | null>(null);

  /* ---- UI-050 review session ----
   * The document owns decisions + note edits (revision-bound); the session
   * owns the undo/redo command stack. `docVersion` bumps after every
   * mutation so memos/effects that read the document recompute. */
  const sessionRef = useRef<ReviewSession | null>(null);
  if (sessionRef.current === null) {
    sessionRef.current = new ReviewSession(scoreDoc);
  }
  const session = sessionRef.current;
  const [docVersion, setDocVersion] = useState(0);
  const bumpDoc = useCallback(() => setDocVersion((v) => v + 1), []);
  /* #115: engine rhythm edits are async — serialize them on a promise
   *  chain so a fast key repeat builds on the newest content instead of
   *  racing two score.edit calls against the same revision. */
  const rhythmQueueRef = useRef<Promise<void>>(Promise.resolve());

  const allIssues = useMemo(
    () => session.issues(),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [session, docVersion],
  );
  const pendingCount = useMemo(
    () => session.pendingCount(),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [session, docVersion],
  );
  const copy = useMemo(inspectorCopy, []);

  followRef.current = followEnabled;
  suspendedRef.current = followSuspended;
  zoomRef.current = zoom;
  viewModeRef.current = viewMode;
  currentPageRef.current = currentPage;
  pitchRef.current = pitch;
  reviewIndexRef.current = reviewIndex;
  reviewOpenRef.current = reviewOpen;

  /* ------------------------- DOM-only mark appliers ------------------------- */

  const applyActiveDom = useCallback((canonicals: ReadonlySet<string>) => {
    const idx = indexRef.current;
    const container = scrollRef.current;
    if (!idx || !container) return;
    markCanonicalSet(idx, canonicals, ACTIVE_CLASS);
    const els: Element[] = [];
    for (const id of canonicals) els.push(...(idx.byCanonical.get(id) ?? []));
    markMeasures(container, els, MEASURE_ACTIVE_CLASS, true);
    // Playback caret: thin bar at the onset of the earliest active fragment.
    clearCaret(container);
    const first = els[0];
    if (first) {
      const measure = measureElementOf(first);
      if (measure && typeof (first as SVGGElement).getBBox === "function") {
        try {
          const box = (first as SVGGElement).getBBox();
          drawCaret(measure, box.x);
        } catch {
          /* no geometry — caret skipped, marks still applied */
        }
      }
    }
  }, []);

  const applyLoopDom = useCallback((canonicals: ReadonlySet<string>) => {
    const idx = indexRef.current;
    if (!idx) return;
    markCanonicalSet(idx, canonicals, LOOP_CLASS);
  }, []);

  const scrollCanonicalIntoView = useCallback((canonicals: ReadonlySet<string>) => {
    const idx = indexRef.current;
    if (!idx || canonicals.size === 0) return;
    const table = tableRef.current;
    let target: Element | null = null;
    if (table) {
      // Earliest onset leads the scroll target.
      let best = Number.POSITIVE_INFINITY;
      for (const id of canonicals) {
        const onset = table.onsetMsByCanonical.get(id) ?? Number.POSITIVE_INFINITY;
        if (onset < best) {
          best = onset;
          target = idx.byCanonical.get(id)?.[0] ?? null;
        }
      }
    }
    target ??= idx.byCanonical.get([...canonicals][0])?.[0] ?? null;
    target?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }, []);

  /* ------------------------------ rendering ------------------------------ */

  /** (Re)load + re-render the current presentation. Preserves the viewport
   *  ratio so the Concert↔F管 switch keeps an equivalent scroll position. */
  const renderScore = useCallback(
    (view: PitchViewSetting, opts: { keepScroll?: boolean } = {}) => {
      const r = rendererRef.current;
      const container = scrollRef.current;
      if (!r) return;
      if (opts.keepScroll && container) {
        const denom = Math.max(1, container.scrollHeight - container.clientHeight);
        pendingScrollRef.current = { ratio: container.scrollTop / denom };
      }
      try {
        r.setViewMode(viewModeRef.current);
        r.setZoom(zoomRef.current);
        const xml = scoreDoc.musicXml(view);
        const ok = r.load(xml);
        const parsed = ok ? parseScoreDoc(xml) : null;
        // UI-003 finding: loadData returns true for truncated-but-parseable
        // XML — verify content, not just the flag.
        if (!ok || !parsed || parsed.notes.length === 0) {
          throw new Error("score load produced no content");
        }
        renderedPitchRef.current = view;
        setPages(r.renderAllPages());
        setRenderError(false);
        setLoading(false);
      } catch {
        setPages([]);
        setRenderError(true);
        setLoading(false);
      }
    },
    [scoreDoc],
  );

  /** After every (re)render of the SVG: rebuild the element index and
   *  reapply selection/active/loop/caret marks — this is how all context
   *  survives zoom re-renders and Concert↔F管 switches (UI-005 pattern). */
  useLayoutEffect(() => {
    const container = scrollRef.current;
    if (!container || pages.length === 0) return;
    indexRef.current = buildElementIndex(container);
    markReviewMarkers(
      container,
      indexRef.current,
      markedCanonicalIds(scoreDoc.reviewIssues()),
    );
    const sel = selectionRef.current;
    if (sel?.canonicalId) {
      markCanonical(indexRef.current, sel.canonicalId, SELECTED_CLASS);
    } else if (sel) {
      indexRef.current.byExportId.get(sel.exportId)?.classList.add(SELECTED_CLASS);
    }
    markCanonicalSet(indexRef.current, activeRef.current, ACTIVE_CLASS);
    markCanonicalSet(indexRef.current, loopCanonicalsRef.current, LOOP_CLASS);
    const actEls: Element[] = [];
    for (const id of activeRef.current) {
      actEls.push(...(indexRef.current.byCanonical.get(id) ?? []));
    }
    markMeasures(container, actEls, MEASURE_ACTIVE_CLASS, true);

    // Page mode: clamp the current page when the document repaginates
    // (zoom / view switch can change the page count).
    if (viewModeRef.current === "page" && currentPageRef.current > pages.length) {
      setCurrentPage(pages.length);
    }

    // Equivalent viewport position (issue §Context preservation): a
    // selection re-reveals its note; otherwise the scroll ratio carries over.
    const pending = pendingScrollRef.current;
    pendingScrollRef.current = null;
    if (sel?.canonicalId) {
      indexRef.current.byCanonical
        .get(sel.canonicalId)?.[0]
        ?.scrollIntoView({ block: "nearest", inline: "nearest" });
    } else if (pending && viewModeRef.current === "continuous") {
      const denom = Math.max(1, container.scrollHeight - container.clientHeight);
      container.scrollTop = pending.ratio * denom;
    }
    // viewMode/currentPage swap the rendered DOM in page mode — the element
    // index must be rebuilt or marks would land on detached nodes.
    // docVersion re-applies review marks after a decision resolves an issue
    // without re-rendering the SVG.
  }, [pages, scoreDoc, viewMode, currentPage, docVersion]);

  /* ------------------------------ init ----------------------------------- */

  // Init per mounted document (App remounts on revision change via `key`).
  // StrictMode-safe: no "did init" latch — the cleanup's `cancelled` flag is
  // the guard, so the replayed effect initializes cleanly.
  useEffect(() => {
    let cancelled = false;
    getScoreRenderer()
      .then((r) => {
        if (cancelled) return;
        rendererRef.current = r;
        // Parse both presentations once — inspector reads both regardless of
        // the current view (written/concert rows, §22).
        const concert = parseScoreDoc(scoreDoc.musicXml("concert"));
        const horn = parseScoreDoc(scoreDoc.musicXml("hornF"));
        docsRef.current = {
          concert,
          horn,
          concertByCanonical: notesByCanonical(concert),
          hornByCanonical: notesByCanonical(horn),
          concertByExport: notesByExportId(concert),
          hornByExport: notesByExportId(horn),
        };
        renderScore(pitchRef.current);
        // Canonical timing is identical across presentations (same
        // durations + tempo), so the playback table is built once.
        tableRef.current = buildPlaybackTable(r.timemap());
        const clock = new ScoreCursorClock(tableRef.current.durationMs);
        clockRef.current = clock;
        clock.subscribe(setClockSnap);
        // FEAT-001: audition engine follows the score clock. It consumes
        // the same PlaybackTable + the CONCERT ParsedNote map (sounding
        // pitch — the written horn view never drives pitch, because the
        // audition exists to check the transcribed *sounding* result).
        const synth = new ScorePlaybackSynth();
        synthRef.current = synth;
        synth.load(tableRef.current, notesByCanonical(concert));
        clock.subscribe((s) => {
          synth.setLoop(s.loop ? { startMs: s.loop.startMs, endMs: s.loop.endMs } : null);
          synth.sync(s.positionMs, s.isPlaying, s.rate);
        });
      })
      .catch((e: unknown) =>
        setInitError(e instanceof Error ? e.message : String(e)),
      );
    return () => {
      cancelled = true;
      clockRef.current?.dispose();
      clockRef.current = null;
      synthRef.current?.dispose();
      synthRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ---- media transport handoff (UI-020 → UI-030) ----
   * The media element is the authoritative audio clock once a source is
   * loaded: the score clock follows its play state and snaps to its
   * position on real drift (seek, waveform click, rate change). Without a
   * live transport the score clock stays self-driven (fixture playback). */
  const extPlaying = transport?.isPlaying;
  const extSec = transport?.positionSec;
  const extRate = transport?.rate;
  useEffect(() => {
    if (extPlaying == null || extSec == null) return;
    const clock = clockRef.current;
    if (!clock) return;
    if (extPlaying !== clock.isPlaying()) {
      if (extPlaying) clock.play();
      else clock.pause();
    }
    if (extRate != null && extRate !== clock.rate()) clock.setRate(extRate);
    // Snap on real divergence only — the media timeupdate cadence is
    // coarser than the rAF clock, so small deltas are left alone.
    if (Math.abs(clock.positionMs() - extSec * 1000) > 200) {
      clock.seek(extSec * 1000);
    }
  }, [extPlaying, extSec, extRate]);

  /* --------------------- per-frame sync pump (DOM-only) -------------------- */
  /* Reads the transport clock each frame; DOM marks apply only when the     */
  /* active canonical set changes — React state never updates at frame rate. */

  useEffect(() => {
    let raf = 0;
    const tick = () => {
      const clock = clockRef.current;
      const table = tableRef.current;
      const idx = indexRef.current;
      if (clock && table && idx) {
        const seg = segmentAt(table, clock.positionMs());
        const set = seg?.canonicalIds ?? EMPTY_SET;
        if (!sameSet(set, activeRef.current)) {
          activeRef.current = set;
          applyActiveDom(set);
          if (
            followRef.current &&
            !suspendedRef.current &&
            clock.isPlaying() &&
            set.size > 0
          ) {
            if (viewModeRef.current === "page") {
              const r = rendererRef.current;
              const exportId = table.exportIdsByCanonical.get([...set][0])?.[0];
              const page = exportId && r ? r.pageWithElement(exportId) : 0;
              if (page > 0 && page !== currentPageRef.current) {
                setCurrentPage(page);
              }
            } else {
              scrollCanonicalIntoView(set);
            }
          }
        }
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [applyActiveDom, scrollCanonicalIntoView]);

  // Loop range → score passage marks (UI-005: half-open overlap semantics).
  useEffect(() => {
    const table = tableRef.current;
    if (!table) return;
    const loop = clockSnap.loop;
    const set = loop ? canonicalsInRange(table, loop.startMs, loop.endMs) : new Set<string>();
    if (!sameSet(set, loopCanonicalsRef.current)) {
      loopCanonicalsRef.current = set;
      applyLoopDom(set);
    }
  }, [clockSnap.loop, applyLoopDom]);

  /* --------------------------- selection -------------------------------- */

  const reportInspector = useCallback(() => {
    const docs = docsRef.current;
    const sel = selectionRef.current;
    if (!docs) return;
    if (!sel) {
      onInspectorChange(
        buildScoreInspector(scoreDoc.meta, pendingCount, copy),
      );
      return;
    }
    const canonical = sel.canonicalId;
    const concertFrags = canonical
      ? (docs.concertByCanonical.get(canonical) ?? [])
      : [docs.concertByExport.get(sel.exportId) ?? docs.hornByExport.get(sel.exportId)]
          .filter((n): n is ParsedNote => n != null);
    const hornFrags = canonical
      ? (docs.hornByCanonical.get(canonical) ?? [])
      : concertFrags;
    const onsetMs = canonical
      ? (tableRef.current?.onsetMsByCanonical.get(canonical) ?? null)
      : null;
    onInspectorChange(
      buildNoteInspector({
        canonicalId: canonical,
        concert: concertFrags,
        written: hornFrags,
        onsetMs,
        // UI-050: all issues for the note (open AND decided) — the status
        // label column keeps resolved rows readable in the inspector.
        issues: canonical
          ? allIssuesForCanonical(scoreDoc.reviewIssues(), canonical)
          : [],
        copy,
      }),
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scoreDoc, pendingCount, docVersion, copy, onInspectorChange]);

  /** Select by export id; canonical notes also seek the transport to the
   *  note onset (§10: 原音位置と対応). */
  const selectExportId = useCallback(
    (exportId: string, opts: { seek?: boolean; scroll?: boolean } = {}) => {
      const canonicalId = canonicalNoteIdFromMusicxml(exportId);
      const sel: Selection = { exportId, canonicalId };
      selectionRef.current = sel;
      setSelection(sel);
      const idx = indexRef.current;
      if (idx) {
        markCanonical(idx, canonicalId, SELECTED_CLASS);
        if (!canonicalId) {
          idx.byExportId.get(exportId)?.classList.add(SELECTED_CLASS);
        }
      }
      reportInspector();
      const parsed =
        (canonicalId
          ? docsRef.current?.concertByCanonical.get(canonicalId)?.[0]
          : docsRef.current?.concertByExport.get(exportId)) ??
        docsRef.current?.hornByExport.get(exportId);
      if (parsed) announce(describeNote(parsed));
      const onsetMs = canonicalId
        ? tableRef.current?.onsetMsByCanonical.get(canonicalId)
        : undefined;
      if (opts.seek !== false && onsetMs != null) {
        clockRef.current?.seek(onsetMs);
      }
      if (opts.scroll && idx) {
        idx.byCanonical.get(canonicalId ?? "")?.[0]?.scrollIntoView({
          block: "nearest",
          inline: "nearest",
        });
      }
    },
    [announce, reportInspector],
  );

  const clearSelection = useCallback(() => {
    selectionRef.current = null;
    setSelection(null);
    const idx = indexRef.current;
    if (idx) markCanonical(idx, null, SELECTED_CLASS);
    reportInspector();
    announce(ja.scoreView.deselected);
  }, [announce, reportInspector]);

  /* --------------------------- follow mode ------------------------------- */

  const suspendFollow = useCallback(() => {
    // Only meaningful while playback is actually following (§11); a paused
    // score can scroll freely without nagging the user.
    if (!followRef.current || suspendedRef.current || !clockRef.current?.isPlaying()) {
      return;
    }
    suspendedRef.current = true;
    setFollowSuspended(true);
  }, []);

  const resumeFollow = useCallback(() => {
    suspendedRef.current = false;
    setFollowSuspended(false);
    setFollowEnabled(true);
    followRef.current = true;
    scrollCanonicalIntoView(activeRef.current);
  }, [scrollCanonicalIntoView]);

  /* ---------------------------- view switch ------------------------------ */
  /* Concert↔F管: re-render the other presentation. Canonical ids, the       */
  /* transport clock, selection, loop and zoom are all view-independent —    */
  /* marks reapply in the layout effect above; playback never pauses.        */

  useEffect(() => {
    if (!rendererRef.current || pitch === renderedPitchRef.current) return;
    renderScore(pitch, { keepScroll: true });
  }, [pitch, renderScore]);

  const changeZoom = useCallback(
    (pct: number) => {
      const next = clampScoreZoom(pct);
      if (next === zoomRef.current) return;
      zoomRef.current = next;
      setZoom(next);
      writeScoreSessionView({ zoomPct: next });
      renderScore(pitchRef.current, { keepScroll: true });
    },
    [renderScore],
  );

  const zoomFit = useCallback(() => {
    const container = scrollRef.current;
    const svg = container?.querySelector(".hs-score-page > svg");
    if (!container || !svg) return;
    const width = svg.getBoundingClientRect().width;
    if (width <= 0) return;
    const target = Math.floor((container.clientWidth - 32) * (zoomRef.current / width));
    changeZoom(target);
  }, [changeZoom]);

  const changeViewMode = useCallback(
    (mode: ScoreViewMode) => {
      if (mode === viewModeRef.current) return;
      viewModeRef.current = mode;
      setViewMode(mode);
      writeScoreSessionView({ viewMode: mode });
      renderScore(pitchRef.current, { keepScroll: true });
    },
    [renderScore],
  );

  /* ------------------------------ review --------------------------------- */
  /* UI-050: the cursor walks the FULL issue list (resolved issues stay
   *  reachable so their status/decision can be revisited and undone);
   *  markers + pendingCount come from the still-open subset. */

  const issueAtCursor = useCallback(
    () => allIssues[reviewIndexRef.current] ?? null,
    [allIssues],
  );

  const gotoIssue = useCallback(
    (index: number) => {
      const issues = allIssues;
      if (issues.length === 0) return;
      const i = ((index % issues.length) + issues.length) % issues.length;
      reviewIndexRef.current = i;
      setReviewIndex(i);
      const issue = issues[i];
      const table = tableRef.current;
      const canonicalId = issue.canonicalNoteIds[0];
      const exportId = canonicalId
        ? table?.exportIdsByCanonical.get(canonicalId)?.[0]
        : undefined;
      if (exportId) {
        // Page mode: jump to the containing page first — the layout effect
        // re-applies the selection mark on the freshly shown page.
        if (viewModeRef.current === "page") {
          const r = rendererRef.current;
          const page = r ? r.pageWithElement(exportId) : 0;
          if (page > 0 && page !== currentPageRef.current) {
            setCurrentPage(page);
          }
        }
        selectExportId(exportId, {
          scroll: viewModeRef.current !== "page",
        });
        // Select ALL associated canonical notes visually — an issue may
        // span several (e.g. a tie chain); the first stays the canonical
        // selection for the inspector.
        const idx = indexRef.current;
        if (idx && issue.canonicalNoteIds.length > 1) {
          markCanonicalSet(idx, new Set(issue.canonicalNoteIds), SELECTED_CLASS);
        }
      }
      // Position the source cursor at the issue's range start so
      // 元音源を再生 is immediate (acceptance: replay without extra steps).
      const startSec = issue.timeRange?.startSec;
      if (startSec != null) sourceControl?.seekTo(startSec);
      announce(ja.review.position(i + 1, issues.length));
    },
    [allIssues, selectExportId, sourceControl, announce],
  );

  const openReview = useCallback(() => {
    if (allIssues.length === 0) {
      announce(ja.review.feedback.noIssues);
      return;
    }
    reviewOpenRef.current = true;
    setReviewOpen(true);
    // Enter on the first still-open issue; when everything is resolved the
    // bar shows the all-done state at the top of the list.
    const firstOpen = allIssues.findIndex((i) => i.status === "open");
    gotoIssue(firstOpen >= 0 ? firstOpen : 0);
  }, [allIssues, gotoIssue, announce]);

  const exitReview = useCallback(() => {
    reviewOpenRef.current = false;
    setReviewOpen(false);
    announce(ja.review.feedback.exited);
  }, [announce]);

  /** Re-parse presentations + re-render after a note edit (pitch/delete):
   *  inspector labels and the playback table both derive from the XML. */
  const reloadEditedScore = useCallback(() => {
    const concert = parseScoreDoc(scoreDoc.musicXml("concert"));
    const horn = parseScoreDoc(scoreDoc.musicXml("hornF"));
    docsRef.current = {
      concert,
      horn,
      concertByCanonical: notesByCanonical(concert),
      hornByCanonical: notesByCanonical(horn),
      concertByExport: notesByExportId(concert),
      hornByExport: notesByExportId(horn),
    };
    renderScore(pitchRef.current, { keepScroll: true });
    const r = rendererRef.current;
    if (r) tableRef.current = buildPlaybackTable(r.timemap());
  }, [scoreDoc, renderScore]);

  /** Apply a session action: bump the document version so derived views
   *  (markers, inspector, counts) refresh; reload the score when the edit
   *  changed notation. Returns false on a no-op (caller announces). */
  const runReviewEdit = useCallback(
    (
      edit: ReviewEdit | null,
      feedback: string,
      opts: { reload?: boolean } = {},
    ): boolean => {
      if (!edit) return false;
      bumpDoc();
      if (opts.reload ?? (edit.noteChanges.length > 0 || edit.docSwap != null)) {
        reloadEditedScore();
      }
      reportInspector();
      announce(feedback);
      return true;
    },
    [bumpDoc, reloadEditedScore, reportInspector, announce],
  );

  const reviewAccept = useCallback(() => {
    const issue = issueAtCursor();
    if (!issue) return;
    if (!runReviewEdit(session.decide(issue.id, "accepted"), ja.review.feedback.accepted)) {
      announce(ja.review.feedback.already(ja.reviewStatus.accepted));
    }
  }, [issueAtCursor, session, runReviewEdit, announce]);

  const reviewDismiss = useCallback(() => {
    const issue = issueAtCursor();
    if (!issue) return;
    if (!runReviewEdit(session.decide(issue.id, "dismissed"), ja.review.feedback.dismissed)) {
      announce(ja.review.feedback.already(ja.reviewStatus.dismissed));
    }
  }, [issueAtCursor, session, runReviewEdit, announce]);

  const reviewPitch = useCallback(
    (delta: number) => {
      const issue = issueAtCursor();
      if (!issue) return;
      if (!runReviewEdit(session.adjustPitch(issue.id, delta), ja.review.feedback.pitchFixed, { reload: true })) {
        announce(ja.review.feedback.noIssues);
      }
    },
    [issueAtCursor, session, runReviewEdit, announce],
  );

  const reviewDeleteOrRestore = useCallback(() => {
    const issue = issueAtCursor();
    if (!issue || issue.canonicalNoteIds.length === 0) return;
    const deleted = session.isDeleted(issue.canonicalNoteIds[0]);
    runReviewEdit(
      session.setNoteDeleted(issue.id, !deleted),
      deleted ? ja.review.feedback.noteRestored : ja.review.feedback.noteDeleted,
      { reload: true },
    );
  }, [issueAtCursor, session, runReviewEdit]);

  /* #114 (spec 10/13): score-workspace note navigation + direct edits.
   *  Arrow keys walk canonical notes in document order; Alt+arrows /
   *  Delete / E edit the selection through the shared undo stack. */
  const selectAdjacentNote = useCallback(
    (direction: 1 | -1) => {
      const docs = docsRef.current;
      if (!docs) return;
      const canonicals = docs.concert.notes
        .map((n) => n.canonicalId)
        .filter((id): id is string => id != null);
      if (canonicals.length === 0) return;
      const cur = selectionRef.current?.canonicalId ?? null;
      let next: string;
      if (cur == null) {
        next = direction === 1 ? canonicals[0] : canonicals[canonicals.length - 1];
      } else {
        const i = canonicals.indexOf(cur);
        const j = i < 0 ? (direction === 1 ? 0 : canonicals.length - 1) : i + direction;
        if (j < 0 || j >= canonicals.length) return; // stay at the edges
        next = canonicals[j];
      }
      const exportId = docs.concertByCanonical.get(next)?.[0]?.exportId;
      if (exportId) selectExportId(exportId, { scroll: true });
    },
    [selectExportId],
  );

  const editSelectedPitch = useCallback(
    (delta: number) => {
      const canonicalId = selectionRef.current?.canonicalId;
      if (!canonicalId) return;
      if (
        !runReviewEdit(
          session.editNote(canonicalId, {
            pitchDelta: session.noteEditOf(canonicalId).pitchDelta + delta,
          }),
          ja.review.feedback.pitchFixed,
          { reload: true },
        )
      ) {
        announce(ja.review.feedback.noIssues);
      }
    },
    [session, runReviewEdit, announce],
  );

  const toggleSelectedDeleted = useCallback(() => {
    const canonicalId = selectionRef.current?.canonicalId;
    if (!canonicalId) return;
    const deleted = session.isDeleted(canonicalId);
    runReviewEdit(
      session.editNote(canonicalId, { deleted: !deleted }),
      deleted ? ja.review.feedback.noteRestored : ja.review.feedback.noteDeleted,
      { reload: true },
    );
  }, [session, runReviewEdit]);

  const toggleSelectedEnharmonic = useCallback(() => {
    const canonicalId = selectionRef.current?.canonicalId;
    if (!canonicalId) return;
    const cur = session.noteEditOf(canonicalId).enharmonic ?? false;
    if (
      !runReviewEdit(
        session.editNote(canonicalId, { enharmonic: !cur }),
        ja.review.feedback.respelled,
        { reload: true },
      )
    ) {
      announce(ja.review.feedback.noIssues);
    }
  }, [session, runReviewEdit, announce]);

  /* #115 (spec 13): engine rhythm edits — duration ladder, onset grid
   *  shift, tie toggle. The engine re-realizes the affected measures
   *  and returns fresh MusicXML + a new revision; the document swaps
   *  its content in place so selection and this undo stack survive
   *  (a remount would lose both). Undo restores the previous snapshot
   *  through the shared ReviewSession stack. */
  const applyRhythmEdit = useCallback(
    (buildOp: (canonical: unknown) => RhythmEditOp | null, feedback: string) => {
      if (!onRhythmEdit || !scoreDoc.replaceContent) {
        announce(ja.commandFeedback.rhythmEditUnavailable);
        return;
      }
      // Serialize engine edits: each call must see the newest content.
      rhythmQueueRef.current = rhythmQueueRef.current.then(async () => {
        const canonical = scoreDoc.canonicalDocument?.();
        const prev = scoreDoc.contentSnapshot?.();
        if (canonical == null || !prev) {
          announce(ja.commandFeedback.rhythmEditUnavailable);
          return;
        }
        const op = buildOp(canonical);
        if (!op) {
          announce(ja.commandFeedback.rhythmEditFailed);
          return;
        }
        try {
          const result = await onRhythmEdit(canonical, op);
          const next = {
            concertXml: result.musicXmlConcert,
            hornXml: result.musicXmlHornF,
            revisionId: result.scoreRevision,
            canonicalDocument: result.scoreDocument,
          };
          scoreDoc.replaceContent?.(next);
          session.commitDocSwap(prev, next);
          bumpDoc();
          reloadEditedScore();
          reportInspector();
          announce(feedback);
        } catch {
          announce(ja.commandFeedback.rhythmEditFailed);
        }
      });
    },
    [
      scoreDoc,
      onRhythmEdit,
      session,
      bumpDoc,
      reloadEditedScore,
      reportInspector,
      announce,
    ],
  );

  /** 音価を2倍/半分 — the duration ladder walks ×2/÷2 on the canonical
   *  note's written length (a quarter → half → whole ...). */
  const noteDurationScale = useCallback(
    (power: number) => {
      const canonicalId = selectionRef.current?.canonicalId;
      if (!canonicalId) return;
      applyRhythmEdit(
        (canonical) => {
          const note = findCanonicalNote(canonical, canonicalId);
          if (!note) return null;
          const next = scaleFraction(note.durationBeats, power);
          if (!next) return null;
          return {
            kind: "setDuration",
            noteId: canonicalId,
            durationBeats: formatFraction(next),
          };
        },
        ja.commandFeedback.rhythmEdited,
      );
    },
    [applyRhythmEdit],
  );

  /** 発音位置を左/右へ — shift the onset by whole minimum-grid steps. */
  const shiftSelectedOnset = useCallback(
    (steps: number) => {
      const canonicalId = selectionRef.current?.canonicalId;
      if (!canonicalId) return;
      applyRhythmEdit(
        () => ({ kind: "shiftOnset", noteId: canonicalId, steps }),
        ja.commandFeedback.rhythmEdited,
      );
    },
    [applyRhythmEdit],
  );

  /** 次の音符とタイで結ぶ/解く — the engine validates the contiguous
   *  same-pitch partner and reports a rejection honestly. */
  const toggleSelectedTie = useCallback(() => {
    const canonicalId = selectionRef.current?.canonicalId;
    if (!canonicalId) return;
    applyRhythmEdit(
      () => ({ kind: "toggleTie", noteId: canonicalId }),
      ja.commandFeedback.tieToggled,
    );
  }, [applyRhythmEdit]);

  /* spec 14 BPM edit - the properties panel's tempo field commits here.
   * setTempo is note-independent (it rewrites the tempo map's head
   * segment), so the op carries no noteId; the engine still returns a
   * fresh revision + rebuilt XML, which keeps undo on the same stack. */
  const setTempo = useCallback(
    (bpm: number) => {
      applyRhythmEdit(
        () => ({ kind: "setTempo", noteId: "", bpm }),
        ja.commandFeedback.tempoChanged,
      );
    },
    [applyRhythmEdit],
  );

  /* #129 (spec 14): meter edit — the engine re-tiles every part under
   * the new signature (positions rescale when the beat unit changes);
   * same serialized queue + undo stack as the other rhythm edits. */
  const setMeter = useCallback(
    (beatsPerMeasure: number, beatUnit: number) => {
      applyRhythmEdit(
        () => ({
          kind: "setMeter",
          noteId: "",
          beatsPerMeasure,
          beatUnit,
        }),
        ja.commandFeedback.meterChanged,
      );
    },
    [applyRhythmEdit],
  );

  /* #130 (spec 14): re-quantize the whole score under changed
   * quantization settings — the engine replays the canonical notes
   * through the DP with the merged profile. */
  const requantize = useCallback(
    (settings: Record<string, unknown>) => {
      applyRhythmEdit(
        () => ({ kind: "requantize", noteId: "", settings }),
        ja.commandFeedback.requantized,
      );
    },
    [applyRhythmEdit],
  );

  /* #131 (spec 13 post-MVP): split at the grid-snapped midpoint; merge
   * with the contiguous next same-pitch note — the engine validates
   * both (too short to split, different pitch, non-contiguous) and
   * reports a rejection honestly. */
  const splitSelectedNote = useCallback(() => {
    const canonicalId = selectionRef.current?.canonicalId;
    if (!canonicalId) return;
    applyRhythmEdit(
      () => ({ kind: "splitNote", noteId: canonicalId }),
      ja.commandFeedback.noteSplit,
    );
  }, [applyRhythmEdit]);

  const mergeSelectedNotes = useCallback(() => {
    const canonicalId = selectionRef.current?.canonicalId;
    if (!canonicalId) return;
    applyRhythmEdit(
      () => ({ kind: "mergeNotes", noteId: canonicalId }),
      ja.commandFeedback.notesMerged,
    );
  }, [applyRhythmEdit]);

  const reviewUndo = useCallback(() => {
    const edit = session.undo();
    if (!edit) {
      announce(ja.review.feedback.nothingToUndo);
      return;
    }
    bumpDoc();
    if (edit.noteChanges.length > 0 || edit.docSwap != null) reloadEditedScore();
    reportInspector();
    announce(ja.review.feedback.undone);
  }, [session, bumpDoc, reloadEditedScore, reportInspector, announce]);

  const reviewRedo = useCallback(() => {
    const edit = session.redo();
    if (!edit) {
      announce(ja.review.feedback.nothingToRedo);
      return;
    }
    bumpDoc();
    if (edit.noteChanges.length > 0 || edit.docSwap != null) reloadEditedScore();
    reportInspector();
    announce(ja.review.feedback.redone);
  }, [session, bumpDoc, reloadEditedScore, reportInspector, announce]);

  /** 元音源を再生 — loop the issue's source range. The media transport is
   *  driven when a source is loaded (sourceControl); the score clock loop
   *  arms either way so the passage indication (LOOP_CLASS) shows which
   *  notes the audio range covers. */
  const playSource = useCallback(() => {
    const issue = issueAtCursor();
    if (!issue) return;
    let startSec = issue.timeRange?.startSec;
    let endSec = issue.timeRange?.endSec;
    if (startSec == null || endSec == null) {
      // No explicit range: loop the canonical note's notated span.
      const table = tableRef.current;
      const first = issue.canonicalNoteIds[0];
      const onset = first ? table?.onsetMsByCanonical.get(first) : undefined;
      if (!table || onset == null) return;
      startSec = onset / 1000;
      endSec = nearestOffset(table, onset) / 1000;
    }
    const clock = clockRef.current;
    clock?.setLoop({ startMs: startSec * 1000, endMs: endSec * 1000 });
    if (sourceControl) {
      sourceControl.setLoop({ start: startSec, end: endSec });
      sourceControl.seekTo(startSec);
      sourceControl.play();
    } else {
      clock?.seek(startSec * 1000);
      clock?.play();
    }
    announce(ja.review.feedback.playingSource);
  }, [issueAtCursor, sourceControl, announce]);

  /* --------------------------- controller -------------------------------- */

  useEffect(() => {
    if (!controllerRef) return;
    const controller: ScoreWorkspaceController = {
      zoomIn: () => changeZoom(zoomRef.current + SCORE_ZOOM_STEP_PCT),
      zoomOut: () => changeZoom(zoomRef.current - SCORE_ZOOM_STEP_PCT),
      zoomFit: () => zoomFit(),
      clearSelection: () => {
        if (reviewOpenRef.current) exitReview();
        else clearSelection();
      },
      togglePlayPause: () => clockRef.current?.togglePlayPause(),
      stop: () => clockRef.current?.stop(),
      seekToStart: () => clockRef.current?.seek(0),
      seekToEnd: () => {
        const c = clockRef.current;
        if (c) c.seek(c.durationMs());
      },
      jumpBy: (deltaMs) => clockRef.current?.jumpBy(deltaMs),
      toggleLoop: () => {
        const c = clockRef.current;
        if (!c) return;
        if (c.loopRange()) c.setLoop(null);
        else {
          // No waveform range selection yet (UI-020) — arm the loop over
          // the selected note's span when possible so Ctrl+L is honest.
          const sel = selectionRef.current;
          const table = tableRef.current;
          if (sel?.canonicalId && table) {
            const onset = table.onsetMsByCanonical.get(sel.canonicalId);
            if (onset != null) {
              const next = nearestOffset(table, onset);
              c.setLoop({ startMs: onset, endMs: next });
            }
          } else {
            c.setLoop({ startMs: 0, endMs: c.durationMs() });
          }
        }
      },
      // #113: expose the armed loop so the app can mirror it onto the
      // media transport (audio loops together with the score marks).
      loopRange: () => clockRef.current?.loopRange() ?? null,
      resumeFollow: () => resumeFollow(),
      setFollowEnabled: (on) => {
        if (on) resumeFollow();
        else {
          setFollowEnabled(false);
          followRef.current = false;
          suspendedRef.current = false;
          setFollowSuspended(false);
        }
      },
      // FEAT-001: audition toggle — driven from the transport bar.
      toggleAudition: () => {
        const synth = synthRef.current;
        if (!synth) return;
        const next = !auditionRef.current;
        auditionRef.current = next;
        setAuditionEnabled(next);
        synth.setEnabled(next);
        announce(
          next
            ? "楽譜の自動演奏をオンにしました"
            : "楽譜の自動演奏をオフにしました",
        );
      },
      openReview: () => openReview(),
      reviewNext: () => gotoIssue(reviewIndexRef.current + 1),
      reviewPrevious: () => gotoIssue(reviewIndexRef.current - 1),
      reviewAccept: () => reviewAccept(),
      reviewDismiss: () => reviewDismiss(),
      reviewPlaySource: () => playSource(),
      reviewPitch: (delta) => reviewPitch(delta),
      reviewDeleteOrRestore: () => reviewDeleteOrRestore(),
      exitReview: () => exitReview(),
      undo: () => reviewUndo(),
      redo: () => reviewRedo(),
      // #114: score-workspace navigation + direct note edits (spec 10/13).
      selectAdjacentNote: (direction) => selectAdjacentNote(direction),
      editSelectedPitch: (delta) => editSelectedPitch(delta),
      toggleSelectedDeleted: () => toggleSelectedDeleted(),
      toggleSelectedEnharmonic: () => toggleSelectedEnharmonic(),
      // #115: engine rhythm edits (spec 13) — duration ladder, onset
      // grid shift, tie toggle. Async internally; feedback announces.
      noteDurationScale: (power) => noteDurationScale(power),
      shiftSelectedOnset: (steps) => shiftSelectedOnset(steps),
      toggleSelectedTie: () => toggleSelectedTie(),
      setTempo: (bpm) => setTempo(bpm),
      setMeter: (bpm_, bu) => setMeter(bpm_, bu),
      requantize: (settings) => requantize(settings),
      splitSelectedNote: () => splitSelectedNote(),
      mergeSelectedNotes: () => mergeSelectedNotes(),
    };
    controllerRef(controller);
    return () => controllerRef(null);
  }, [
    controllerRef,
    changeZoom,
    zoomFit,
    clearSelection,
    exitReview,
    resumeFollow,
    openReview,
    gotoIssue,
    reviewAccept,
    reviewDismiss,
    playSource,
    reviewPitch,
    reviewDeleteOrRestore,
    reviewUndo,
    reviewRedo,
    selectAdjacentNote,
    editSelectedPitch,
    toggleSelectedDeleted,
    toggleSelectedEnharmonic,
    noteDurationScale,
    shiftSelectedOnset,
    toggleSelectedTie,
    setTempo,
    setMeter,
    requantize,
    splitSelectedNote,
    mergeSelectedNotes,
    announce,
  ]);



  /* --------------------------- state mirror ------------------------------ */

  useEffect(() => {
    onStateChange?.({
      hasSelection: selection !== null,
      isPlaying: clockSnap.isPlaying,
      loopEnabled: clockSnap.loop !== null,
      positionMs: clockSnap.positionMs,
      durationMs: clockSnap.durationMs,
      followEnabled,
      followSuspended,
      reviewOpen,
      zoomPct: zoom,
      canUndo: session.canUndo,
      canRedo: session.canRedo,
      openIssueCount: pendingCount,
      auditionEnabled,
    });
  }, [
    selection,
    clockSnap,
    followEnabled,
    followSuspended,
    reviewOpen,
    zoom,
    onStateChange,
    session,
    pendingCount,
    docVersion,
    auditionEnabled,
  ]);

  // Initial inspector = score summary (§22 "Nothing selected").
  useEffect(() => {
    if (!loading) reportInspector();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading]);

  /* ------------------------------- render -------------------------------- */

  const visiblePages =
    viewMode === "page" ? pages.filter((p) => p.page === currentPage) : pages;
  const s = ja.scoreView;

  if (initError) {
    return (
      <div className="hs-score-error" role="alert">
        <h2>{s.renderErrorTitle}</h2>
        <p>{initError}</p>
      </div>
    );
  }

  return (
    <div className="hs-score-workspace">
      <div className="hs-score-toolbar" role="toolbar" aria-label={s.regionLabel}>
        <SegmentedControl
          options={[
            { value: "continuous", label: s.continuous },
            { value: "page", label: s.page },
          ]}
          value={viewMode}
          onChange={(v) => changeViewMode(v)}
          ariaLabel={s.viewModeLabel}
        />
        {viewMode === "page" && pages.length > 1 && (
          <span className="hs-score-toolbar__pages">
            <HsButton
              size="small"
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              disabled={currentPage <= 1}
            >
              {s.prevPage}
            </HsButton>
            <span aria-live="polite">{s.pagePosition(currentPage, pages.length)}</span>
            <HsButton
              size="small"
              onClick={() => setCurrentPage((p) => Math.min(pages.length, p + 1))}
              disabled={currentPage >= pages.length}
            >
              {s.nextPage}
            </HsButton>
          </span>
        )}
        {pitch === "hornF" && (
          <span className="hs-score-toolbar__caption">
            {ja.pitch.hornF}（{ja.pitch.writtenNote}）
          </span>
        )}
        <span className="hs-score-toolbar__spacer" />
        <HsButton size="small" onClick={() => changeZoom(zoom - SCORE_ZOOM_STEP_PCT)}>
          {s.zoomOut}
        </HsButton>
        <span className="hs-score-toolbar__zoom" aria-live="polite" aria-label={s.zoomLabel}>
          {zoom}%
        </span>
        <HsButton size="small" onClick={() => changeZoom(zoom + SCORE_ZOOM_STEP_PCT)}>
          {s.zoomIn}
        </HsButton>
        <HsButton size="small" onClick={zoomFit}>
          {s.zoomFit}
        </HsButton>
      </div>

      {reviewOpen && (
        <ReviewBar
          index={Math.min(reviewIndex, Math.max(0, allIssues.length - 1))}
          total={allIssues.length}
          pending={pendingCount}
          issue={allIssues[reviewIndex] ?? null}
          copy={
            allIssues[reviewIndex]
              ? {
                  reasonTitle: copy.review.reasonTitle(
                    allIssues[reviewIndex].reason,
                  ),
                  reasonDetail: copy.review.reasonDetail(
                    allIssues[reviewIndex],
                  ),
                  severityLabel: copy.review.severityLabel(
                    allIssues[reviewIndex].severity,
                  ),
                  statusLabel: copy.review.statusLabel(
                    allIssues[reviewIndex].status,
                  ),
                }
              : null
          }
          noteDeleted={
            allIssues[reviewIndex]?.canonicalNoteIds[0] != null &&
            session.isDeleted(allIssues[reviewIndex].canonicalNoteIds[0])
          }
          canUndo={session.canUndo}
          canRedo={session.canRedo}
          onPrev={() => gotoIssue(reviewIndexRef.current - 1)}
          onNext={() => gotoIssue(reviewIndexRef.current + 1)}
          onPlaySource={playSource}
          onAccept={reviewAccept}
          onDismiss={reviewDismiss}
          onPitch={reviewPitch}
          onDeleteOrRestore={reviewDeleteOrRestore}
          onUndo={reviewUndo}
          onRedo={reviewRedo}
          onExit={exitReview}
        />
      )}

      {loading && <div className="hs-score-loading">{s.loading}</div>}
      {renderError && (
        <div className="hs-score-error" role="alert">
          <h2>{s.renderErrorTitle}</h2>
          <p>{s.renderErrorBody}</p>
          <HsButton onClick={() => renderScore(pitchRef.current)}>{ja.common.retry}</HsButton>
        </div>
      )}
      {!renderError && (
        <ScoreView
          ref={scrollRef}
          pages={visiblePages}
          onElementClick={(id) => selectExportId(id)}
          onBackgroundClick={clearSelection}
          onUserNavigate={suspendFollow}
          ariaLabel={s.regionLabel}
        />
      )}

      {followSuspended && (
        <div className="hs-score-follownote" role="status">
          <span>{s.followPaused}</span>
          <HsButton size="small" variant="primary" onClick={resumeFollow}>
            {s.resumeFollow}
          </HsButton>
        </div>
      )}
    </div>
  );
}

/** Offset ms for a canonical id — the next distinct onset after its own,
 *  or the document end. Used to arm a note-span loop. */
function nearestOffset(table: PlaybackTable, onsetMs: number): number {
  let best = Number.POSITIVE_INFINITY;
  for (const t of table.onsetMsByCanonical.values()) {
    if (t > onsetMs && t < best) best = t;
  }
  return Number.isFinite(best) ? best : table.durationMs;
}

